from pathlib import Path
import json,math,hashlib,re
from PIL import Image
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'data/book-bank';rows=[];crops=[];seq={}
TITLES={'ctst':'Sách bài tập Vật lí 12 · Chân trời sáng tạo','sbt-kntt':'Sách bài tập Vật lí 12 · Kết nối tri thức'}
def nu(a,z,x):return f'{{}}^{{{a}}}_{{{z}}}\\mathrm{{{x}}}'
def fig(book,name,page,box):
 src=OUT/f'{book}/pages/{page:03}.jpg';im=Image.open(src);w,h=im.size;rect=[round(box[0]*w),round(box[1]*h),round(box[2]*w),round(box[3]*h)]
 file=f'{book}/verified-figures/{name}.png';target=OUT/file;target.parent.mkdir(exist_ok=True);im.crop(rect).save(target)
 crops.append({'id':f'{book}-original-{name}','book':book,'page':page,'label':name,'image':{'file':file,'page':page,'rect':rect,'width':rect[2]-rect[0],'height':rect[3]-rect[1]},'status':'isolated_visual_check','colorStatus':'original','sourceSha256':hashlib.sha256(src.read_bytes()).hexdigest()})
 return {'url':'/api/book-bank/asset?file='+file.replace('/','%2F'),'description':'Hình minh họa của bài','origin':'source_crop'}
def add(book,label,page,topic,prompt,answer,bloom='understand',kind='written',options=None,key=None,statements=None,figure=None,status='ready'):
 answer=re.sub(r'\\n(?=Dùng|Số |Đổi |\$)', '\n', answer)
 seq[book]=seq.get(book,0)+1;n=seq[book]
 rationale={'remember':'Nhớ lại định nghĩa, tính chất hoặc quy tắc đã học.','understand':'Diễn giải, so sánh hoặc giải thích ý nghĩa vật lí.','apply':'Thực hiện quy tắc hoặc phép tính với dữ kiện của bài.','analyze':'Phân tách thông tin và liên hệ các thành phần để tìm kết quả.','evaluate':'Đưa ra nhận định theo tiêu chí và bằng chứng.','create':'Xây dựng phương án hoặc sản phẩm đáp ứng yêu cầu.'}[bloom]
 q={'id':f'{book}-nuclear-{n:03}','kind':kind,'topic':topic,'chapter':'Vật lí hạt nhân','level':{'remember':'Nhận biết','understand':'Thông hiểu'}.get(bloom,'Vận dụng'),'prompt':prompt,'explanation':answer,'points':1,'source':{'book':TITLES[book],'bookId':book,'sequence':n,'label':label,'pages':[page],'printedPages':[page]},'bloom':{'level':bloom,'rationale':rationale,'review':'reviewed'},'status':status,'notes':['Phần dẫn và phương án đối chiếu ảnh trang sách; lời giải do người biên soạn kiểm tra.','Nhãn Bloom là phân loại nội bộ, chưa thẩm định độc lập; mức độ ma trận được rà soát riêng.']}
 if options:q.update(options=options,answer=key)
 if statements:q['statements']=[{'text':t,'answer':a} for t,a in statements]
 if kind=='numeric':q['answerText']=answer.split('\n')[0]
 if figure:q['figure']=figure
 rows.append(q);return q
B='ctst'
add(B,'Câu 14.1',61,'B21','Cặp nguyên tử của các hạt nhân nào sau đây không được gọi là đồng vị?','D. Hai hạt nhân có Z khác nhau nên không là đồng vị.','understand','choice',[r'$^{35}_{17}\mathrm{Cl},{}^{37}_{17}\mathrm{Cl}$',r'$^{1}_{1}\mathrm{H},{}^{2}_{1}\mathrm{D}$',r'$^{63}_{29}\mathrm{Cu},{}^{65}_{29}\mathrm{Cu}$',r'$^{3}_{1}\mathrm{H},{}^{3}_{2}\mathrm{He}$'],3)
add(B,'Câu 14.2',61,'B21','Các nguyên tử được gọi là đồng vị khi hạt nhân của chúng có cùng','D. Cùng số proton, khác số neutron.','remember','choice',['khối lượng.','số neutron.','số nucleon.','số proton.'],3)
add(B,'Câu 14.3',61,'B21','Hạt nhân nào sau đây có 136 neutron?',r'C. $222-86=136$. Giữ đúng kí hiệu Ra với Z=86 in trong sách; đây là lỗi kí hiệu nguyên tố của nguồn (Ra đúng là Z=88). Câu cần xác minh trước khi dùng.','apply','choice',[r'$^{23}_{11}\mathrm{Na}$',r'$^{238}_{92}\mathrm{U}$',r'$^{222}_{86}\mathrm{Ra}$',r'$^{209}_{84}\mathrm{Po}$'],2,status='draft')
add(B,'Câu 14.4',61,'B21',r'Sử dụng công thức về bán kính hạt nhân, hãy cho biết bán kính hạt nhân $^{207}_{82}\mathrm{Pb}$ lớn hơn bán kính hạt nhân $^{27}_{13}\mathrm{Al}$ bao nhiêu lần.',r'C. Tỉ số $(207/27)^{1/3}\approx1{,}97$.','apply','choice',['hơn 2,5 lần.','hơn 2 lần.','gần 2 lần.','1,5 lần.'],2)
add(B,'Câu 14.5',61,'B21','Phát biểu nào sau đây sai?','A. Đồng vị không bền có thể có nguồn gốc tự nhiên.','understand','choice',['Đồng vị bền chỉ có nguồn gốc tự nhiên, đồng vị không bền chỉ có nguồn gốc nhân tạo.','Các nguyên tử mà hạt nhân có cùng số proton nhưng có số neutron khác nhau gọi là đồng vị.','Các đồng vị của cùng một nguyên tố có số neutron khác nhau nhưng tính chất hóa học giống nhau.','Các đồng vị của cùng một nguyên tố có cùng vị trí trong bảng hệ thống tuần hoàn.'],0)
add(B,'Câu 14.6',61,'B21','Trong các nhận định sau đây về kết quả thí nghiệm tán xạ của hạt alpha lên lá vàng mỏng, có bao nhiêu nhận định đúng?\n(1) Phần lớn các hạt alpha xuyên thẳng qua lá vàng mỏng.\n(2) Một tỉ lệ khá lớn các hạt alpha bị lệch khỏi hướng ban đầu với góc lệch lớn hơn 90°.\n(3) Một tỉ lệ rất nhỏ các hạt alpha bị lệch khỏi hướng ban đầu với góc lệch lớn hơn 90°.\n(4) Một số ít hạt alpha bị lệch khỏi phương ban đầu với những góc lệch khác nhau.','C. Các nhận định (1), (3), (4) đúng.','understand','choice',['1.','2.','3.','4.'],2)
add(B,'Câu 14.7',62,'B21',r'So với hạt nhân $^{12}_{6}\mathrm{C}$, hạt nhân $^{56}_{27}\mathrm{Co}$ có nhiều hơn',r'B. Chênh số neutron: $(56-27)-(12-6)=23$; chênh số proton: $27-6=21$.','apply','choice',['44 neutron và 21 proton.','23 neutron và 21 proton.','44 neutron và 23 proton.','23 neutron và 23 proton.'],1)
add(B,'Câu 14.8',62,'B21',r'Trong nguyên tử của đồng vị phóng xạ $^{210}_{90}\mathrm{Th}$ có','B. Nguyên tử trung hòa có 90 proton, 90 electron, 120 neutron.','apply','choice',['90 electron, tổng số proton và electron bằng 210.','90 proton, tổng số neutron và electron bằng 210.','90 neutron, tổng số neutron và electron bằng 210.','90 neutron, tổng số proton và electron bằng 210.'],1)
add(B,'Câu 14.9',62,'B21','Trong mỗi phát biểu sau, em hãy chọn đúng hoặc sai.','a) Sai; b) Đúng theo điện động lực học cổ điển; c) Sai; d) Sai; e) Đúng; f) Đúng; g) Đúng vì e=Z và A=Z+N; h) Đúng theo mô hình trạng thái dừng.','understand','true_false',statements=[('Hạt nhân nguyên tử trung hòa về điện.',False),('Một hệ quả của mẫu nguyên tử Rutherford là tính không bền của nguyên tử do electron mất năng lượng khi chuyển động có gia tốc.',True),('Hạt nhân nguyên tử được cấu tạo từ proton, neutron và electron.',False),('Điện tích dương trong nguyên tử phân bố đều, xen kẽ với các electron nên nguyên tử trung hòa về điện.',False),('Có thể xem khối lượng hạt nhân xấp xỉ bằng khối lượng nguyên tử.',True),(r'Nguyên tử của đồng vị $^{60}_{27}\mathrm{Co}$ có 27 proton, 33 neutron và 27 electron.',True),('Khi nguyên tử trung hòa về điện, tổng số electron và neutron bằng số khối của hạt nhân nguyên tử.',True),('Nguyên tử chỉ tồn tại trong các trạng thái có năng lượng xác định, gọi là các trạng thái dừng. Khi ở trạng thái dừng, nguyên tử không phát xạ.',True)])
add(B,'Câu 14.10',63,'B21',r'Biết số Avogadro là $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$, khối lượng mol của uranium $^{238}_{92}\mathrm{U}$ là 238 g/mol. Số neutron trong 238 gam $^{238}_{92}\mathrm{U}$ là',r'A. $146N_A\approx8{,}8\times10^{25}$ neutron.','apply','choice',[r'$8{,}8\times10^{25}$',r'$1{,}2\times10^{25}$',r'$4{,}4\times10^{25}$',r'$2{,}2\times10^{25}$'],0)
add(B,'Câu 14.11',63,'B21',r'Số proton trong 17,5 gam $^{238}_{92}\mathrm{U}$ là',r'C. $(17{,}5/238)N_A\times92\approx4{,}07\times10^{24}$ hạt.','apply','choice',[r'$3{,}01\times10^{23}$ hạt.',r'$27{,}7\times10^{24}$ hạt.',r'$4{,}07\times10^{24}$ hạt.',r'$7{,}07\times10^{25}$ hạt.'],2)
add(B,'Bài 14.1',63,'B21','Điền các số liệu còn thiếu vào bảng sau.\nO: số proton 8; số neutron …; số khối 16; kí hiệu hạt nhân …\nK: số proton …; số neutron 20; số khối 39; kí hiệu hạt nhân …\nNa: số proton 11; số neutron 12; số khối …; kí hiệu hạt nhân …',r'O: 8 neutron, $^{16}_{8}\mathrm{O}$. K: 19 proton, $^{39}_{19}\mathrm{K}$. Na: A=23, $^{23}_{11}\mathrm{Na}$.','apply')
add(B,'Bài 14.2',63,'B21',r'Chọn cụm từ thích hợp để điền vào chỗ trống. Các cụm từ: số hiệu nguyên tử; tổng số proton và neutron; $10^{-15}$ m – $10^{-14}$ m; không phát xạ; trung tâm của nguyên tử; năng lượng xác định; bán kính; năng lượng; bảng tuần hoàn hóa học; rỗng; giảm dần; các hạt nhân; hạt nhân nguyên tử; proton Z; fm (femtômét); phát ra năng lượng; nucleon.'+'\na) Đồng vị là những nguyên tử mà (1)… của chúng có cùng số (2)… nhưng có số neutron N khác nhau.\nb) Số proton trong hạt nhân Z bằng (3)… và bằng số thứ tự của nguyên tố trong (4)…\nc) Phần lớn không gian bên trong nguyên tử là (5)…, toàn bộ điện tích dương tập trung ở một vùng có (6)… rất nhỏ, nằm ở (7)… gọi là (8)…\nd) Nguyên tử chỉ tồn tại trong một số trạng thái có (9)… gọi là trạng thái dừng. Ở trạng thái dừng, nguyên tử (10)…\ne) Bán kính hạt nhân có giá trị trong khoảng (11)…\nf) Bán kính hạt nhân thường được đo bằng đơn vị (12)…\ng) Trong hạt nhân nguyên tử, các hạt proton và neutron gọi chung là (13)… Vì vậy, số nucleon trong hạt nhân được tính bằng (14)…\nh) Theo lí thuyết trường điện từ, khi electron chuyển động có gia tốc sẽ (15)… Vậy nên khi electron chuyển động trên quỹ đạo tròn, electron sẽ mất (16)…, tốc độ của electron (17)… và cuối cùng rơi vào hạt nhân.',r'(1) các hạt nhân; (2) proton Z; (3) số hiệu nguyên tử; (4) bảng tuần hoàn hóa học; (5) rỗng; (6) bán kính; (7) trung tâm của nguyên tử; (8) hạt nhân nguyên tử; (9) năng lượng xác định; (10) không phát xạ; (11) $10^{-15}$ m – $10^{-14}$ m; (12) fm (femtômét); (13) nucleon; (14) tổng số proton và neutron; (15) phát ra năng lượng; (16) năng lượng; (17) giảm dần. Ý h giữ nội dung sách nhưng cần giải thích quỹ đạo Coulomb cổ điển: khi năng lượng giảm, electron xoáy vào và tốc độ quỹ đạo tăng; chưa giao câu này khi chưa làm rõ.','remember',status='draft')
add(B,'Bài 14.3',64,'B21',r'Tính bán kính của các hạt nhân nguyên tử $^{4}_{2}\mathrm{He}$, $^{235}_{92}\mathrm{U}$, $^{56}_{26}\mathrm{Fe}$, $^{137}_{55}\mathrm{Cs}$.',r'Dùng $R=1{,}2A^{1/3}$ fm. Các bán kính lần lượt khoảng 1,90; 7,41; 4,59; 6,19 fm.','apply')
add(B,'Bài 14.4',64,'B21',r'Giả sử hạt nhân nguyên tử có dạng hình cầu. Hỏi thể tích hạt nhân $^{56}_{26}\mathrm{Fe}$ gấp bao nhiêu lần thể tích hạt nhân $^{3}_{1}\mathrm{T}$?',r'$56/3\approx18{,}7$ lần. Vì $V\propto R^3\propto A$.','apply','numeric')
add(B,'Bài 14.5',64,'B21','Nêu cấu tạo nguyên tử và viết kí hiệu hạt nhân của các nguyên tử trong các trường hợp sau: a) Carbon; b) Aluminium; c) Nitrogen; d) Silicon (xem hình).',r'a) 6 proton, 6 neutron, 6 electron: $^{12}_{6}\mathrm{C}$. b) 13 proton, 14 neutron, 13 electron: $^{27}_{13}\mathrm{Al}$. c) 7 proton, 7 neutron, 7 electron: $^{14}_{7}\mathrm{N}$. d) 14 proton, 14 neutron, 14 electron: $^{28}_{14}\mathrm{Si}$.','apply',figure=fig(B,'bai-14-5',64,(.18,.372,.917,.838)))
