add(B,'Câu 15.1',65,'B22','Chọn cụm từ phù hợp để hoàn thành nhận định sau: “Khối lượng của một hạt nhân bất kì … tổng khối lượng của các nucleon riêng lẻ cấu tạo thành hạt nhân đó”.','C. Khối lượng giảm do năng lượng liên kết đối với hạt nhân liên kết.','remember','choice',['luôn lớn hơn','luôn bằng','luôn nhỏ hơn','có lúc lớn hơn, có lúc nhỏ hơn'],2)
add(B,'Câu 15.2',65,'B22',r'Độ hụt khối của một hạt nhân $^{A}_{Z}\mathrm{X}$',r'B. $\Delta m=Zm_p+(A-Z)m_n-m_X$.','remember','choice',['là đại lượng đặc trưng cho mức độ bền vững của hạt nhân.',r'được xác định bằng biểu thức $\Delta m=[Zm_p+(A-Z)m_n]-m_X$.','càng lớn khi số khối của hạt nhân càng lớn.','là đại lượng đặc trưng cho mức độ phổ biến của hạt nhân.'],1)
add(B,'Câu 15.3',65,'B22','Chỉ ra phát biểu sai.','D. Không phải khối lượng mọi hạt nhân đều lớn hơn A amu.','understand','choice',[r'Hệ thức Einstein về mối liên hệ giữa năng lượng và khối lượng là $E=mc^2$.','Khối lượng nghỉ là khối lượng của một vật khi ở trạng thái nghỉ.','Khối lượng của một nguyên tử có giá trị gần bằng khối lượng của hạt nhân nguyên tử đó.','Một hạt nhân có số khối A thì khối lượng của nó luôn lớn hơn A (amu).'],3)
add(B,'Câu 15.4',65,'B22','Nhận định nào sau đây sai khi nói về lực hạt nhân?','A. Lực hạt nhân là tương tác mạnh còn dư, không phải lực hấp dẫn.','understand','choice',['Lực hạt nhân có bản chất là lực hấp dẫn vì nó giúp kết nối các nucleon lại với nhau.','Lực hạt nhân có bản chất là lực tương tác mạnh.','Lực hạt nhân có cường độ lớn hơn nhiều lần so với cường độ của lực tĩnh điện.','Lực hạt nhân có phạm vi tác dụng trong bán kính hạt nhân.'],0)
add(B,'Câu 15.5',66,'B22',r'Đồ thị nào dưới đây mô tả gần đúng mối liên hệ giữa năng lượng liên kết riêng ($E_{lkr}$) với số nucleon (A)?','D. Đồ thị tăng nhanh ở hạt nhân nhẹ, đạt đỉnh vùng khối trung bình rồi giảm chậm ở hạt nhân nặng.','understand','choice',['Đồ thị A.','Đồ thị B.','Đồ thị C.','Đồ thị D.'],3,figure=fig(B,'cau-15-5',66,(.17,.133,.926,.463)))
add(B,'Câu 15.6',66,'B22',r'Các hạt nhân $^{12}_{6}\mathrm{C}$, $^{16}_{8}\mathrm{O}$, $^{4}_{2}\mathrm{He}$ có năng lượng liên kết lần lượt là 92,16 MeV; 127,6 MeV; 28,3 MeV. Thứ tự giảm dần về mức độ bền vững của hạt nhân là:',r'B. Năng lượng liên kết riêng O: 7,975; C: 7,68; He: 7,075 MeV/nucleon.','apply','choice',[r'$^{4}_{2}\mathrm{He},{}^{16}_{8}\mathrm{O},{}^{12}_{6}\mathrm{C}$',r'$^{16}_{8}\mathrm{O},{}^{12}_{6}\mathrm{C},{}^{4}_{2}\mathrm{He}$',r'$^{12}_{6}\mathrm{C},{}^{4}_{2}\mathrm{He},{}^{16}_{8}\mathrm{O}$',r'$^{4}_{2}\mathrm{He},{}^{12}_{6}\mathrm{C},{}^{16}_{8}\mathrm{O}$'],1)
add(B,'Câu 15.7',66,'B22',r'Cho khối lượng của proton, neutron, hạt nhân $^{42}_{20}\mathrm{Ca}$, hạt nhân $^{43}_{20}\mathrm{Ca}$ lần lượt là $m_p=1{,}007276$ amu, $m_n=1{,}008665$ amu, $m_{Ca42}=41{,}958622$ amu, $m_{Ca43}=42{,}958770$ amu. Trong mỗi phát biểu sau, em hãy chọn đúng hoặc sai.',r'$\Delta m_{42}=0{,}377528$ amu; $\Delta m_{43}=0{,}386045$ amu; chênh năng lượng liên kết khoảng 7,934 MeV. Năng lượng liên kết riêng Ca-42 khoảng 8,373 MeV/nucleon, Ca-43 khoảng 8,363.','apply','true_false',statements=[(r'$^{43}_{20}\mathrm{Ca}$ và $^{42}_{20}\mathrm{Ca}$ đều là đồng vị của $^{40}_{20}\mathrm{Ca}$.',True),(r'Độ hụt khối của $^{43}_{20}\mathrm{Ca}$ lớn hơn độ hụt khối của $^{42}_{20}\mathrm{Ca}$.',True),(r'Năng lượng liên kết của $^{43}_{20}\mathrm{Ca}$ lớn hơn năng lượng liên kết của $^{42}_{20}\mathrm{Ca}$ một lượng 9,73 MeV.',False),(r'Hạt nhân $^{43}_{20}\mathrm{Ca}$ kém bền vững hơn hạt nhân $^{42}_{20}\mathrm{Ca}$.',True)])
add(B,'Câu 15.8',67,'B22',r'Cho các hạt nhân $^{238}_{92}\mathrm{U}$, $^{235}_{92}\mathrm{U}$, $^{23}_{11}\mathrm{Na}$, $^{197}_{79}\mathrm{Au}$. Sắp xếp theo mức độ bền vững tăng dần, biết khối lượng các hạt nhân lần lượt 238,050788; 234,993422; 22,983730; 196,966552 amu; $m_p=1{,}007276$ amu, $m_n=1{,}008665$ amu.',r'C. Tính $E_{lkr}=[Zm_p+(A-Z)m_n-m]931{,}5/A$, lần lượt khoảng 7,37; 7,59; 8,11; 7,71 MeV/nucleon.','apply','choice',[r'$^{23}_{11}\mathrm{Na},{}^{197}_{79}\mathrm{Au},{}^{235}_{92}\mathrm{U},{}^{238}_{92}\mathrm{U}$',r'$^{238}_{92}\mathrm{U},{}^{235}_{92}\mathrm{U},{}^{23}_{11}\mathrm{Na},{}^{197}_{79}\mathrm{Au}$',r'$^{238}_{92}\mathrm{U},{}^{235}_{92}\mathrm{U},{}^{197}_{79}\mathrm{Au},{}^{23}_{11}\mathrm{Na}$',r'$^{23}_{11}\mathrm{Na},{}^{197}_{79}\mathrm{Au},{}^{238}_{92}\mathrm{U},{}^{235}_{92}\mathrm{U}$'],2)
add(B,'Câu 15.9',67,'B22',r'Cho khối lượng proton, neutron, hạt nhân $^{3}_{1}\mathrm{T}$ và $^{244}_{95}\mathrm{Am}$ lần lượt 1,007276; 1,008665; 3,016049; 244,064279 amu. Nhận xét nào sau đây đúng?',r'B. Độ hụt khối T=0,008557 amu; Am=1,918026 amu.','apply','choice',['Hai hạt nhân này có độ hụt khối bằng nhau.',r'Năng lượng liên kết của $^{244}_{95}\mathrm{Am}$ lớn hơn năng lượng liên kết của $^{3}_{1}\mathrm{T}$.',r'Năng lượng liên kết riêng của $^{244}_{95}\mathrm{Am}$ nhỏ hơn năng lượng liên kết riêng của $^{3}_{1}\mathrm{T}$.',r'Mức độ bền vững của hai hạt nhân $^{3}_{1}\mathrm{T}$ và $^{244}_{95}\mathrm{Am}$ là bằng nhau.'],1)
add(B,'Bài 15.1',67,'B22',r'Tính năng lượng liên kết của $^{27}_{13}\mathrm{Al}$, biết khối lượng của hạt nhân $^{27}_{13}\mathrm{Al}$, proton và neutron lần lượt $m_{Al}=26{,}97435$ amu, $m_p=1{,}00728$ amu, $m_n=1{,}00867$ amu.',r'$225{,}116$ MeV.\n$\Delta m=0{,}24167$ amu; $E_{lk}=\Delta mc^2=0{,}24167\times931{,}5$.','apply','numeric')
add(B,'Bài 15.2',67,'B22',r'Tính năng lượng liên kết riêng của $^{30}_{15}\mathrm{P}$, biết khối lượng của hạt nhân $^{30}_{15}\mathrm{P}$, proton và neutron lần lượt $m_P=29{,}97005$ amu, $m_p=1{,}00728$ amu, $m_n=1{,}00867$ amu.',r'$8{,}35866$ MeV/nucleon.\n$\Delta m=0{,}26920$ amu; $E_{lkr}=0{,}26920\times931{,}5/30$.','apply','numeric')
add(B,'Bài 15.3',67,'B22',r'Hình 15.1 cho thấy sự phụ thuộc của năng lượng liên kết riêng theo số khối ở một số hạt nhân. Dựa vào Hình 15.1, sắp xếp mức độ bền vững theo thứ tự giảm dần của $^{126}_{52}\mathrm{Te}$, $^{238}_{92}\mathrm{U}$, $^{180}_{72}\mathrm{Hf}$, $^{56}_{26}\mathrm{Fe}$, $^{209}_{83}\mathrm{Bi}$, $^{110}_{48}\mathrm{Cd}$. Từ đó, nhận xét tính bền vững của các hạt nhân khối lượng lớn (từ sau Fe) theo chiều tăng dần số khối.',r'Fe, Cd, Te, Hf, Bi, U. Theo các điểm trong hình, từ vùng Fe, năng lượng liên kết riêng có xu hướng giảm khi A tăng; không dùng độ phổ biến tự nhiên làm tiêu chí độ bền.','analyze',figure=fig(B,'hinh-15-1',68,(.065,.043,1,.575)))
add(B,'Bài 15.4',68,'B22',r'Hạt nhân $^{56}_{26}\mathrm{Fe}$ là một trong những hạt nhân bền vững nhất trong tự nhiên (độ phổ biến 91,754% trữ lượng các đồng vị sắt), trong khi hạt nhân nhẹ deuteri $^{2}_{1}\mathrm{D}$ lại kém bền (độ phổ biến khoảng 0,015% trữ lượng các đồng vị hydrogen). Năng lượng liên kết riêng của Fe lớn hơn D bao nhiêu lần? Cho $m_{Fe}=55{,}93494$ amu, $m_D=2{,}01355$ amu, $m_p=1{,}00728$ amu, $m_n=1{,}00867$ amu.',r'Khoảng $7{,}66$ lần.\nDùng độ hụt khối, chia năng lượng liên kết cho A; Fe≈8,55716; D≈1,11780 MeV/nucleon. Độ phổ biến không phải nguyên nhân hay thước đo duy nhất của độ bền.','apply','numeric')
add(B,'Bài 15.5',68,'B22',r'Xét hai hạt nhân X và Y: số proton X bằng số neutron Y và ngược lại, được gọi là cặp hạt nhân gương. Xét $^{23}_{12}\mathrm{Mg}$ và $^{23}_{11}\mathrm{Na}$ có khối lượng lần lượt $m_{Mg}=22{,}99413$ amu, $m_{Na}=22{,}98373$ amu. Hạt nhân nào có năng lượng liên kết lớn hơn và lớn hơn bao nhiêu MeV? Biết $m_p=1{,}00728$ amu, $m_n=1{,}00867$ amu.',r'Na lớn hơn khoảng $10{,}982385$ MeV. $E_{Mg}=175{,}650465$ MeV; $E_{Na}=186{,}632850$ MeV.','apply')
add(B,'Bài 15.6',69,'B22',r'Cần bắn photon có năng lượng tối thiểu bằng bao nhiêu vào hạt nhân deuteri $^{2}_{1}\mathrm{D}$ (một neutron và một proton) để phân tách thành một neutron và một proton riêng rẽ? Biết $m_D=2{,}01355$ amu, $m_p=1{,}00728$ amu, $m_n=1{,}00867$ amu.',r'$2{,}2356$ MeV theo mô hình bỏ qua giật lùi của bài.\n$\Delta m=0{,}00240$ amu; $E_{lk}=\Delta mc^2$.','apply','numeric')
add(B,'Bài 15.7',69,'B22',r'Bắn photon năng lượng 3,6 MeV vào hạt nhân deuteri $^{2}_{1}\mathrm{D}$ để phân tách thành neutron và proton riêng rẽ. Ngoài phân tách, photon còn cung cấp động năng ban đầu. Xác định động lượng proton và neutron nếu giả sử động năng sau phân tách bằng nhau. Lấy $m_D=2{,}01355$ amu, $m_p=1{,}00728$ amu, $m_n=1{,}00867$ amu.',r'Mỗi hạt có K=(3,6−2,2356)/2=0,6822 MeV. Dùng $p=\sqrt{2mc^2K}/c$ với $mc^2$ đổi từ amu sang MeV: proton≈35,78 MeV/c; neutron≈35,80 MeV/c. Đáp án cuối sách thiếu hệ số đổi amu và có sai đơn vị; không sao chép sai số ấy.','apply')
# CTST B16–B18, all original question positions.
add(B,'Câu 16.1',69,'B22',r'Cho phản ứng hạt nhân: $^{19}_{9}\mathrm{F}+{}^{1}_{1}\mathrm{H}\to{}^{16}_{8}\mathrm{O}+X$. X là hạt',r'A. X có A=4, Z=2, là alpha.','apply','choice',['alpha.','neutron.','deuteri.','proton.'],0)
add(B,'Câu 16.2',69,'B22','Phản ứng nhiệt hạch là','Các lựa chọn trong bản sách không có định nghĩa đầy đủ của nhiệt hạch; D là mô tả quá rộng (phân hạch cũng tỏa năng lượng). Giữ nguyên để rà soát, chưa đưa vào đề.','remember','choice',['sự biến đổi hạt nhân dưới tác dụng nhiệt.','sự phân rã của một hạt nhân thành những hạt nhân khác một cách tự phát.','phản ứng trong đó một hạt nhân nặng vỡ thành các hạt nhân nhẹ hơn.','phản ứng hạt nhân tỏa năng lượng.'],3,status='draft')
add(B,'Câu 16.3',69,'B22','Trong các phát biểu sau về phản ứng phân hạch và phản ứng nhiệt hạch, có bao nhiêu phát biểu đúng?\n(1) Đều là phản ứng hạt nhân tỏa năng lượng.\n(2) Đều là hiện tượng một hạt nhân nặng vỡ ra thành các hạt nhân nhẹ hơn.\n(3) Đều là phản ứng tổng hợp hạt nhân.\n(4) Đều xảy ra sự biến đổi hạt nhân.','B. (1), (4) đúng theo các phản ứng năng lượng được xét trong sách.','understand','choice',['1.','2.','3.','4.'],1)
add(B,'Câu 16.4',70,'B22','Trong một phản ứng hạt nhân, luôn có sự bảo toàn','B. Tổng số nucleon được bảo toàn trong các phản ứng ở phạm vi SGK.','remember','choice',['số proton.','số nucleon.','số neutron.','khối lượng.'],1)
add(B,'Câu 16.5',70,'B22',r'Hạt nhân $^{234}_{92}\mathrm{U}$ phát ra hạt $^{4}_{2}\alpha$ và biến đổi thành hạt nhân mới, phương trình phản ứng của quá trình này có dạng:',r'B. Bảo toàn A: 234=4+230, Z: 92=2+90.','apply','choice',[r'$^{234}_{92}\mathrm{U}\to{}^{4}_{2}\alpha+{}^{232}_{90}\mathrm{U}$',r'$^{234}_{92}\mathrm{U}\to{}^{4}_{2}\alpha+{}^{230}_{90}\mathrm{Th}$',r'$^{234}_{92}\mathrm{U}\to{}^{4}_{2}\alpha+{}^{230}_{88}\mathrm{Th}$',r'$^{234}_{92}\mathrm{U}\to{}^{4}_{2}\alpha+{}^{230}_{90}\mathrm{U}$'],1)
add(B,'Câu 16.6',70,'B22',r'Một trong các phản ứng xảy ra trong lò phản ứng là $^{1}_{0}\mathrm{n}+{}^{235}_{92}\mathrm{U}\to{}^{236}_{92}\mathrm{U}\to{}^{143}_{57}\mathrm{La}+{}^{87}_{35}\mathrm{Br}+y({}^{1}_{0}\mathrm{n})$ với y là số neutron. Giá trị y bằng',r'B. $y=236-143-87=6$.','apply','choice',['4.','6.','8.','10.'],1)
add(B,'Câu 16.7',70,'B22','Trong mỗi phát biểu sau, em hãy chọn đúng hoặc sai.','a) Sai vì proton/neutron có thể chuyển hóa; b) Đúng: X có A=140,Z=54,N=86; c) Sai: 17,6 MeV là năng lượng tỏa; d) Đúng; e) Sai vì còn bảo toàn năng lượng toàn phần, động lượng; f) Đúng.','understand','true_false',statements=[('Trong các phản ứng hạt nhân, điện tích và số khối được bảo toàn nên số neutron cũng được bảo toàn.',False),(r'Cho phản ứng $^{1}_{0}\mathrm{n}+{}^{235}_{92}\mathrm{U}\to{}^{94}_{38}\mathrm{Sr}+X+2{}^{1}_{0}\mathrm{n}$. Hạt nhân X có 54 proton và 86 neutron.',True),(r'Trong phản ứng nhiệt hạch $^{2}_{1}\mathrm{H}+{}^{3}_{1}\mathrm{H}\to{}^{4}_{2}\mathrm{He}+{}^{1}_{0}\mathrm{n}+17{,}6$ MeV, năng lượng cần cung cấp cho phản ứng là 17,6 MeV.',False),('Công nghệ hạt nhân đang được ứng dụng nhiều trong y học, công nghiệp, nông nghiệp, khảo cổ học, thực phẩm.',True),('Trong phản ứng hạt nhân chỉ có sự bảo toàn điện tích và bảo toàn số khối.',False),('Phản ứng nhiệt hạch là nguồn năng lượng của Mặt Trời và các sao.',True)])
add(B,'Câu 16.8',70,'B22',r'Xét lần lượt hai phản ứng: (1) $^{235}_{92}\mathrm{U}+{}^{1}_{0}\mathrm{n}\to{}^{143}_{60}\mathrm{Nd}+{}^{90}_{40}\mathrm{Zr}+3{}^{1}_{0}\mathrm{n}+8{}^{0}_{-1}\mathrm{e}+8\mathrm{antineutrino}+200$ MeV, dùng 50 g U-235. (2) $^{1}_{1}\mathrm{H}+{}^{1}_{0}\mathrm{n}\to{}^{2}_{1}\mathrm{D}+2{,}23$ MeV, tạo 50 g D. Biết $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$. Nhận định nào sau đây đúng?',r'D theo giá trị làm tròn trong sách. $Q_2/Q_1=(2{,}23/2)/(200/235)=1{,}310125$; hai năng lượng làm tròn 3,36 và 2,56 cho 1,3125. Phương án D ghi tỉ số không hoàn toàn khớp dữ kiện; cần xác minh.','analyze','choice',[r'Phản ứng 1 thuộc loại nhiệt hạch, năng lượng tỏa ra khi phản ứng hết 50 g U-235 là $2{,}56\times10^{25}$ MeV.',r'Phản ứng 2 thuộc loại phân hạch, năng lượng tỏa ra khi thu được 50 g D là $3{,}36\times10^{25}$ MeV.','Xét năng lượng tỏa ra của một phản ứng thì phản ứng nhiệt hạch có giá trị lớn hơn phản ứng phân hạch.','Tổng năng lượng tỏa ra ở phản ứng 2 lớn gấp 1,3125 lần tổng năng lượng tỏa ra ở phản ứng 1.'],3,status='draft')
add(B,'Câu 16.9',71,'B22',r'Bom hydrogen (bom H) có sức tàn phá lớn hơn bom nguyên tử (bom A), là sự kết hợp của phản ứng phân hạch U-235 (giai đoạn 1) để tạo môi trường nhiệt độ rất cao, cung cấp động năng cho phản ứng nhiệt hạch (giai đoạn 2): $^{2}_{1}\mathrm{H}+{}^{3}_{1}\mathrm{H}\to{}^{4}_{2}\mathrm{He}+{}^{1}_{0}\mathrm{n}+17{,}6$ MeV. Giả sử năng lượng phân hạch còn lại sau khi tạo phản ứng nhiệt hạch là $2{,}8\times10^{10}$ J và khối lượng He tạo thành trong thí nghiệm là 200 g, năng lượng này tương đương khoảng bao nhiêu tấn TNT? Biết một tấn TNT cháy hoàn toàn tỏa $4{,}2\times10^9$ J; $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$.','Theo cách đổi MeV→J được dùng trong đáp án sách, chọn B≈20190,48 tấn. Câu chỉ tính tổng năng lượng và đổi đơn vị.','apply','choice',['20 197,14 tấn.','20 190,48 tấn.','20 166,6 tấn.','20 183,81 tấn.'],1,status='draft')
add(B,'Bài 16.1',71,'B22',r'Xác định số hiệu nguyên tử và số khối còn thiếu trong các phản ứng: a) $^{26}_{12}\mathrm{Mg}+{}^{1}_{0}\mathrm{n}\to{}^{?}_{?}\mathrm{Ne}+{}^{4}_{2}\mathrm{He}$; b) $^{?}_{94}\mathrm{Pu}+{}^{22}_{10}\mathrm{Ne}\to4{}^{1}_{0}\mathrm{n}+{}^{260}_{104}\mathrm{Rf}$; c) $^{2}_{1}\mathrm{H}+{}^{?}_{3}\mathrm{Li}\to2{}^{4}_{2}\mathrm{He}+{}^{1}_{0}\mathrm{n}$.',r'a) $^{23}_{10}\mathrm{Ne}$; b) $^{242}_{94}\mathrm{Pu}$; c) $^{7}_{3}\mathrm{Li}$. Dùng bảo toàn A và điện tích.','apply')
add(B,'Bài 16.2',71,'B22',r'Xét phản ứng nhiệt hạch $^{2}_{1}\mathrm{H}+{}^{3}_{1}\mathrm{H}\to{}^{4}_{2}\mathrm{He}+{}^{1}_{0}\mathrm{n}$. Để tổng hợp được 50 g He thì khối lượng H-2 và H-3 phải sử dụng là bao nhiêu? Coi khối lượng mol gần bằng số khối; $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$.','Cần 25 g H-2 và 37,5 g H-3. Số mol mỗi chất bằng 50/4=12,5 mol.','apply')
add(B,'Bài 16.3',72,'B22',r'Xét phản ứng nhiệt hạch $^{2}_{1}\mathrm{H}+{}^{2}_{1}\mathrm{H}\to{}^{4}_{2}\mathrm{He}$ tỏa 3,25 MeV. Nếu sử dụng hết 150 g H-2 thì tổng năng lượng thu được bao nhiêu? Coi khối lượng mol gần bằng số khối; $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$.',r'$7{,}3393\times10^{25}$ MeV.\nSố phản ứng bằng $(150/2)N_A/2=37{,}5N_A$; nhân 3,25 MeV.','apply','numeric')
add(B,'Bài 16.4',72,'B22',r'Cho neutron có động năng lớn bắn phá hạt nhân $^{235}_{92}\mathrm{U}$ đứng yên: $^{1}_{0}\mathrm{n}+{}^{235}_{92}\mathrm{U}\to{}^{140}_{54}\mathrm{Xe}+{}^{94}_{38}\mathrm{Sr}+x{}^{1}_{0}\mathrm{n}$. a) Xác định x. b) Năng lượng phản ứng bằng hiệu năng lượng liên kết sản phẩm và ban đầu. Năng lượng liên kết riêng U-235 là 7,59 MeV/nucleon, Xe-140 là 8,29 MeV/nucleon, Sr-94 là 8,59 MeV. Tính năng lượng phản ứng.',r'a) x=2. b) Theo dữ kiện trong đề, $Q=140\times8{,}29+94\times8{,}59-235\times7{,}59=176{,}81$ MeV. Dữ kiện Sr-94 in đơn vị MeV nhưng được hiểu là liên kết riêng theo cấu trúc câu; cần xác minh đơn vị.','apply',status='draft')
add(B,'Bài 16.5',72,'B22',r'a) Nhà máy điện hạt nhân công suất phát điện 1920 MW dùng phân hạch U-235, hiệu suất 33%. Mỗi năm 365 ngày; mỗi phân hạch khoảng 200 MeV. Tính khối lượng U-235 tiêu thụ mỗi năm; $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$. b) Cần khối lượng than bao nhiêu trong nhà máy nhiệt điện để tạo lượng năng lượng như trên? Năng suất tỏa nhiệt than 20 MJ/kg.',r'a) $m_U=Pt\times235/(0{,}33\times200\times1{,}602\times10^{-13}N_A)\approx2235$ kg. b) Nếu so sánh nhiệt năng Q trước chuyển đổi: $m_{than}=Q/(20\times10^6)\approx9{,}174\times10^9$ kg. Nếu so sánh điện năng, cần hiệu suất nhà máy than; nêu giả thiết rõ.','analyze')
add(B,'Bài 16.6',72,'B22',r'Năng lượng Mặt Trời và các sao có nguồn gốc từ nhiệt hạch, bắt đầu chu trình proton–proton tạo helium. Xét ngôi sao đã đốt cháy hoàn toàn hydrogen thành helium, tất cả helium tham gia quá trình ba–alpha: $^{4}_{2}\mathrm{He}+{}^{4}_{2}\mathrm{He}+{}^{4}_{2}\mathrm{He}\to{}^{12}_{6}\mathrm{C}+7{,}275$ MeV. Khối lượng sao lúc đó $4\times10^{30}$ kg, công suất tỏa nhiệt $3{,}8\times10^{30}$ W. Sau bao lâu toàn bộ helium chuyển thành carbon? $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$.',r'$t\approx6{,}157\times10^{13}$ s (khoảng 1,95 triệu năm).\nSố phản ứng $N=(4\times10^{33}/12)N_A$; $t=N\times7{,}275\times1{,}602\times10^{-13}/P$.','apply','numeric')
add(B,'Câu 17.1',73,'B23','Chỉ ra phát biểu sai khi nói về hiện tượng phóng xạ.','B. Trong phạm vi SGK, phân rã không phụ thuộc nhiệt độ, áp suất thông thường.','understand','choice',['Hiện tượng phóng xạ là hiện tượng một hạt nhân không bền vững tự phát phân rã, phát ra các tia phóng xạ và biến đổi thành hạt nhân khác.','Hiện tượng phóng xạ chịu ảnh hưởng bởi các yếu tố bên ngoài như nhiệt độ, áp suất,…',r'Có 3 loại phóng xạ là $\alpha$, $\beta$ và $\gamma$; $\beta$ chia thành $\beta^-$ và $\beta^+$.',r'Do tia $\gamma$ có bản chất là sóng điện từ nên phóng xạ $\gamma$ không đi kèm với việc biến đổi hạt nhân mẹ thành hạt nhân khác.'],1)
add(B,'Câu 17.2',73,'B23','Trong các định luật bảo toàn: (1) động lượng; (2) số khối; (3) khối lượng; (4) năng lượng toàn phần; (5) số proton. Hiện tượng phóng xạ tuân theo bao nhiêu định luật bảo toàn?','B. (1), (2), (4) được bảo toàn; tổng khối lượng nghỉ và số proton không luôn bảo toàn.','understand','choice',['2.','3.','4.','5.'],1)
add(B,'Câu 17.3',73,'B23',r'Mẫu chất phóng xạ ban đầu (t=0) có $N_0$ hạt nhân; hằng số phóng xạ và chu kì bán rã lần lượt $\lambda$, T. Sau khoảng thời gian $\Delta t$, số hạt nhân còn lại xác định bằng biểu thức nào?',r'C. $N_t=N_0e^{-\lambda\Delta t}$.','remember','choice',[r'$N_t=N_0e^{\lambda\Delta t}$',r'$N_t=N_0 2^{\frac{\Delta t}{T}}$',r'$N_t=N_0e^{-\lambda\Delta t}$',r'$N_t=N_0 2^{-\Delta t}$'],2)
add(B,'Câu 17.4',74,'B23',r'Có bao nhiêu phát biểu đúng? (1) Chu kì bán rã là thời gian để một nửa số hạt nhân ban đầu bị phân rã. (2) $\lambda=T\ln2$. (3) Tia $\gamma$ thường phát kèm theo các tia $\alpha$ và $\beta$. (4) Độ phóng xạ đặc trưng tính phóng xạ mạnh hay yếu của một lượng chất phóng xạ. (5) Độ phóng xạ tăng dần theo thời gian theo quy luật hàm mũ.','C. (1), (3), (4) đúng; (2) phải là ln2/T; (5) độ phóng xạ giảm trong mẫu đơn đồng vị.','understand','choice',['1.','2.','3.','4.'],2)
add(B,'Câu 17.5',74,'B23','Chiếu 3 chùm tia phóng xạ lần lượt qua tấm giấy, nhôm và chì như Hình 17.1. Các tia 1, tia 2, tia 3 theo thứ tự là:',r'B. Alpha bị giấy chặn, beta xuyên giấy nhưng bị nhôm chặn, gamma đâm xuyên mạnh.','understand','choice',[r'tia $\beta$, tia $\alpha$, tia $\gamma$.',r'tia $\alpha$, tia $\beta$, tia $\gamma$.',r'tia $\beta$, tia $\gamma$, tia $\alpha$.',r'tia $\gamma$, tia $\alpha$, tia $\beta$.'],1,figure=fig(B,'hinh-17-1',74,(.638,.423,.952,.621)))
add(B,'Câu 17.6',74,'B23',r'$^{238}_{92}\mathrm{U}$ có hằng số phóng xạ $4{,}916\times10^{-18}\ \mathrm{s}^{-1}$, phân rã alpha thành X. Trong mỗi phát biểu sau, chọn đúng hoặc sai.',r'a) Đúng; b) Sai vì X là Th-234; c) Đúng, $T=\ln2/\lambda\approx1{,}41\times10^{17}$ s; d) Sai, khối lượng còn khoảng 0,09846 g.','apply','true_false',statements=[('Quá trình phóng xạ của U-238 là một phản ứng hạt nhân tỏa năng lượng.',True),(r'Hạt nhân con X là $^{234}_{92}\mathrm{U}$.',False),(r'Chu kì bán rã U-238 là $1{,}41\times10^{17}$ s (làm tròn đến 2 chữ số thập phân sau dấu phẩy).',True),('Mẫu ban đầu chứa 0,1 g U-238. Sau 100 triệu năm (365 ngày/năm), khối lượng U-238 còn khoảng 0,089 g.',False)])
add(B,'Câu 17.7',75,'B23',r'$^{210}_{84}\mathrm{Po}$ có T=138,4 ngày. Mẫu ban đầu có $N_0$ hạt. Sau bao lâu tỉ số số hạt đã phân rã và số hạt còn lại bằng 7?',r'A. $N_0/N=8$, nên t=3T=415,2 ngày.','apply','choice',['415,2 ngày.','387,5 ngày.','34,6 ngày.','968,8 ngày.'],0)
add(B,'Câu 17.8',75,'B23',r'$^{18}_{9}\mathrm{F}$ dùng chụp PET. Bệnh nhân được tiêm lượng chất có độ phóng xạ 350 Bq trước chụp. Sau bao lâu độ phóng xạ giảm còn 25 Bq? Chu kì bán rã F-18 trong đề là 110 ngày.',r'C theo dữ kiện in: $t=110\log_2(14)\approx418{,}81$ ngày. F-18 thực tế có T khoảng 110 phút, nên lỗi đơn vị ngày cần xác minh; không tự đổi đề rồi giữ phương án ngày.','apply','choice',['378,92 ngày.','427,93 ngày.','418,81 ngày.','125,46 ngày.'],2,status='draft')
add(B,'Câu 17.9',75,'B23',r'Mẫu chất phóng xạ X phân rã phát hạt $\alpha$. Số hạt này được ghi nhận bằng ống Geiger–Muller, biểu diễn theo t như Hình 17.2. Hằng số phóng xạ của chất là',r'A. Từ hai điểm (2 s, 3 ô) và (17 s, 15 ô), giải $(1-e^{-2\lambda})/(1-e^{-17\lambda})=3/15$ cho $\lambda\approx0{,}081\ \mathrm{s}^{-1}$. Đây là số hạt tích lũy, không lấy nửa giá trị lớn nhất làm chu kì.','analyze','choice',[r'$0{,}081\ \mathrm{s}^{-1}$',r'$0{,}173\ \mathrm{s}^{-1}$',r'$0{,}231\ \mathrm{s}^{-1}$',r'$0{,}058\ \mathrm{s}^{-1}$'],0,figure=fig(B,'hinh-17-2',75,(.08,.548,.872,.885)))
add(B,'Bài 17.1',76,'B23',r'Hai mẫu chứa các đồng vị $^{66}_{28}\mathrm{Ni}$ và $^{208}_{82}\mathrm{Pb}$ có hoạt độ lần lượt 438 Bq và 803 Bq. Trong 1 giây, mẫu nào có số hạt nhân phân rã nhiều hơn? Vì sao?','Theo hoạt độ cho, mẫu Pb có trung bình 803 phân rã/s, nhiều hơn Ni. Pb-208 là đồng vị bền nên mâu thuẫn với hoạt độ và mô tả nguồn; cần xác minh.','understand',status='draft')
add(B,'Bài 17.2',76,'B23',r'Đặt nguồn phóng xạ trong điện trường đều giữa hai bản kim loại tích điện trái dấu như Hình 17.3. Vẽ đường đi các tia nếu nguồn phát được $\alpha$, $\beta^+$, $\beta^-$, $\gamma$.',r'Alpha và beta+ lệch sang bản âm bên phải; beta− sang bản dương bên trái; gamma thẳng. Độ cong không đủ dữ kiện định lượng.','apply',figure=fig(B,'hinh-17-3',76,(.338,.282,.711,.557)))
add(B,'Bài 17.3',76,'B23',r'Mẫu ban đầu ($t_0=0$) có $N_0$ hạt, chu kì T. Tính số hạt đã phóng xạ tại t=2T.',r'$3N_0/4$.\nSố hạt còn $N_0/4$, lấy ban đầu trừ còn lại.','apply','numeric')
add(B,'Bài 17.4',76,'B23','Dựa vào kiến thức đã học, giải thích tại sao nhiệt độ một mẫu chất phóng xạ luôn cao hơn nhiệt độ môi trường xung quanh một chút.','Bức xạ và hạt giật lùi truyền năng lượng thành nhiệt trong mẫu. Độ tăng nhiệt tùy công suất phân rã, phần hấp thụ và trao đổi nhiệt; từ “luôn” không đúng tuyệt đối khi mẫu rất yếu hoặc bức xạ thoát ra, cần nêu điều kiện.','understand')
add(B,'Bài 17.5',76,'B23',r'Xác định A, Z trong: a) $^{212}_{83}\mathrm{Bi}\to{}^{A}_{Z}\mathrm{X}+{}^{4}_{2}\mathrm{He}$; b) $^{234}_{90}\mathrm{Th}\to{}^{230}_{88}\mathrm{Ra}+{}^{A}_{Z}\mathrm{X}$; c) $^{210}_{84}\mathrm{Po}\to{}^{A}_{Z}\mathrm{X}+\alpha$; d) $^{12}_{5}\mathrm{B}\to{}^{A}_{Z}\mathrm{X}+\beta^-+\mathrm{antineutrino}$.',r'a) A=208,Z=81 (Tl); b) A=4,Z=2 (He); c) A=206,Z=82 (Pb); d) A=12,Z=6 (C).','apply')
add(B,'Bài 17.6',77,'B23',r'Hạt nhân không bền có thể phân rã nhiều lần tới hạt nhân bền, tạo một họ phóng xạ. Họ thorium bắt đầu ở $^{232}_{90}\mathrm{Th}$, kết thúc ở $^{208}_{82}\mathrm{Pb}$, phương trình thu gọn $^{232}_{90}\mathrm{Th}\to{}^{208}_{82}\mathrm{Pb}+x\beta^-+y\alpha$. Xác định x, y.',r'y=6, x=4. Bảo toàn A: 232=208+4y; điện tích: 90=82−x+2y.','apply')
add(B,'Bài 17.7',77,'B23',r'$^{66}_{28}\mathrm{Ni}$ phát beta− biến thành $^{66}_{29}\mathrm{Cu}$. Khối lượng hạt nhân lần lượt 65,9291; 65,9289 amu; $W=(m_1-m_2)c^2$, với $m_1,m_2$ là tổng khối lượng các hạt trước/sau. a) Viết phương trình. b) Tính năng lượng tỏa.',r'a) Ni-66→Cu-66+electron+antineutrino. b) Nếu đúng là khối lượng hạt nhân, phải trừ khối lượng electron 0,000549 amu, làm Q âm; dữ kiện 0,0002 amu chỉ cho Q≈0,1863 MeV khi hiểu là khối lượng nguyên tử. Cần xác minh trước khi dùng.','analyze',status='draft')
add(B,'Bài 17.8',77,'B23',r'Mẫu than bùn từ đầm lầy cổ chứa 980 µg $^{14}_{6}\mathrm{C}$, T=5730 năm. a) Khối lượng C-14 sau 2000 năm. b) Thời điểm khối lượng còn 100 µg.',r'a) $m=980\times2^{-2000/5730}\approx769{,}4$ µg. b) $t=5730\log_2(980/100)\approx18868$ năm.','apply')
add(B,'Bài 17.9',77,'B23',r'Trước máy gia tốc, bệnh viện dùng nguồn gamma $^{60}_{27}\mathrm{Co}$ để xạ trị, T=5,27 năm (365 ngày/năm). Tính số hạt Co-60 trong nguồn có hoạt độ 5800 Ci.',r'$N\approx5{,}146\times10^{22}$ hạt.\nĐổi H=5800×3,7×10¹⁰ Bq; $N=HT/\ln2$ với T tính bằng giây.','apply','numeric')
add(B,'Bài 17.10',78,'B23',r'Po-210 là nguồn năng lượng được nêu trong bài về máy phát nhiệt điện đồng vị RTG. T=138 ngày, phân rã alpha tạo $^{206}_{82}\mathrm{Pb}$. Mẫu polonium ban đầu nguyên chất; tại $t_1$, tỉ số số hạt Pb tạo thành với số hạt Po còn lại bằng 15. Tại $t_2=t_1+966$ ngày, tỉ số này bằng bao nhiêu?',r'$2047$.\n$t_1=4T$; $966=7T$; t₂=11T nên $N_{Pb}/N_{Po}=2^{11}-1$.','apply','numeric')
add(B,'Bài 17.11',78,'B23',r'Hai máy Geiger–Muller giống nhau đo hai mẫu $^{210}_{84}\mathrm{Po}$ và $^{131}_{53}\mathrm{I}$ ở cùng khoảng cách, hai phòng khác nhau; mỗi hạt phân rã chỉ phát một tia, tín hiệu tỉ lệ số phân rã. Mỗi mẫu ban đầu 1 g; trong ngày đêm đầu máy nào đếm nhiều hơn? Lấy khối lượng mol gần số khối, T lần lượt 138,40 ngày và 8,02 ngày; $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$.',r'$\Delta N=(m/M)N_A(1-2^{-1/T})$. Po≈1,433×10¹⁹, I≈3,806×10²⁰ phân rã. Máy chiếu bởi I đếm nhiều hơn nếu hiệu suất như giả thiết bài.','apply')
add(B,'Bài 17.12',78,'B23',r'Xác định tuổi cổ vật bằng C-14: a) Neutron năng lượng cao trong tia vũ trụ phản ứng với $^{14}_{7}\mathrm{N}$ theo tỉ lệ 1:1 tạo C-14 và X. Viết phản ứng, xác định X. Carbon tạo CO₂, được sinh vật hấp thụ; sau chết không bổ sung C-14 và phân rã beta− với T=5730 năm. b) Viết phương trình phân rã C-14. c) Mảnh gỗ hóa thạch chứa 220 g carbon, hoạt độ 0,52 Bq. Trong gỗ sống tỉ số C-14:C-12=$1{,}3\times10^{-12}$. Tính tuổi, lấy khối lượng mol gần số khối, $N_A\approx6{,}022\times10^{23}\ \mathrm{mol}^{-1}$.',r'a) $^{1}_{0}\mathrm{n}+{}^{14}_{7}\mathrm{N}\to{}^{14}_{6}\mathrm{C}+{}^{1}_{1}\mathrm{H}$, X là proton. b) $^{14}_{6}\mathrm{C}\to{}^{14}_{7}\mathrm{N}+{}^{0}_{-1}\mathrm{e}+\mathrm{antineutrino}$. c) $N_0=(220/12)N_A\times1{,}3\times10^{-12}$; $H_0=(\ln2/T)N_0$; $t=T\ln(H_0/0{,}52)/\ln2\approx38640$ năm (365 ngày/năm).','apply')
add(B,'Câu 18.1',79,'B23',r'Vật liệu nào sau đây hiệu quả nhất để che chắn phóng xạ $\gamma$?','D. Trong bốn vật liệu của bài, chì có khả năng suy giảm gamma tốt nhất khi so sánh theo điều kiện SGK.','remember','choice',['Giấy.','Gỗ.','Nhôm.','Chì.'],3)
add(B,'Câu 18.2',79,'B23','Chọn cụm từ điền chỗ trống: che chắn; phơi nhiễm; khoảng cách; an toàn; màn chắn; kẹp dài.\nBa quy tắc cơ bản để đảm bảo (1)… khi ở khu vực có nguồn hoặc làm việc trực tiếp với nguồn phóng xạ:\n– Bố trí thời lượng công việc để giảm thời gian (2)…\n– Khi thao tác trực tiếp cần đảm bảo (3)… an toàn bằng các (4)… và phương tiện điều khiển từ xa.\n– Việc (5)… thực hiện bằng cách trang bị (6)… như tường bê tông, cửa chì đủ dày, trang phục bảo hộ (mắt kính, găng tay, quần áo có chì).','(1) an toàn; (2) phơi nhiễm; (3) khoảng cách; (4) kẹp dài; (5) che chắn; (6) màn chắn.','remember')
add(B,'Câu 18.3',80,'B23','Trong mỗi phát biểu sau, em hãy chọn đúng hoặc sai.','a) Sai; b) Đúng trong mô hình so sánh tác động khi hấp thụ trong cơ thể; c) Sai; d) Đúng; e) Đúng; f) Cần đối chiếu văn bản y tế gốc và thời điểm áp dụng, không tự dùng phát biểu sách làm quy định hiện hành.','understand','true_false',statements=[(r'Ta có thể dùng tờ giấy mỏng để ngăn chặn tia $\gamma$.',False),(r'Nếu thâm nhập vào cơ thể, chất phóng xạ $\alpha$ gây nguy hại nhiều hơn so với chất phóng xạ $\gamma$.',True),('Một quy tắc an toàn phóng xạ là luôn uống thuốc tân dược để phòng ngừa nhiễm xạ.',False),('Biển cảnh báo đề nghị năm 2007 có nhiều thông tin hơn biển năm 1974.',True),('Khi phát hiện ô nhiễm phóng xạ, thông báo ngay người phụ trách an toàn hoặc chính quyền địa phương.',True),('Bộ Y tế Việt Nam khuyến cáo người làm việc với nguồn phóng xạ khám định kì 2 năm một lần.',False)],status='draft')
add(B,'Câu 18.4',80,'B23',r'Khoảng giữa tháng 3/2015, khi bàn giao tài sản do đổi người phụ trách an toàn bức xạ, nhà máy thép tại Bà Rịa–Vũng Tàu phát hiện nguồn $^{60}_{27}\mathrm{Co}$ thất lạc. Nhà chức trách chỉ đạo khẩn cấp tìm nguồn. Việc tìm kiếm rất quan trọng vì nguồn này','C. Nguồn có thể gây phơi nhiễm nguy hiểm nếu không được kiểm soát.','apply','choice',['rất đắt tiền.','khó sản xuất nên khó tìm thấy trên thị trường.','có thể gây nguy hiểm đến sức khỏe dân cư.','cần thiết trong việc khảo sát sức bền của thép.'],2)
add(B,'Bài 18.1',80,'B23','So sánh hai biển cảnh báo khu vực có chất phóng xạ trong Hình 18.1 và cho biết điểm khác biệt quan trọng giữa hai biển.','Biển a có kí hiệu ba cánh; biển b thêm sọ và người chạy/mũi tên để diễn đạt nguy hiểm và tránh xa rõ hơn cho người chưa hiểu kí hiệu.','understand',figure=fig(B,'hinh-18-1',81,(.103,.053,.874,.305)))
add(B,'Bài 18.2',81,'B23','Quan sát Hình 18.2 và nêu các yếu tố quan trọng trong tuân thủ các quy tắc an toàn phóng xạ.','a) Giảm thời gian; b) Tăng khoảng cách; c) Dùng che chắn thích hợp.','understand',figure=fig(B,'hinh-18-2',81,(.043,.379,.919,.582)))
add(B,'Bài 18.3',81,'B23','Trong sự cố rò rỉ phóng xạ, khi tiếp xúc chất phóng xạ, cởi bỏ trang phục đang mặc có tác dụng giảm khả năng bị nhiễm xạ không? Giải thích.','Có thể loại bỏ chất phóng xạ bám ngoài quần áo, giảm nhiễm bẩn và chiếu xạ tiếp diễn. Không xóa liều đã nhận hay loại chất đã vào cơ thể.','understand')
add(B,'Bài 18.4',81,'B23',r'Radon ($^{222}_{86}\mathrm{Rn}$) và radium ($^{226}_{88}\mathrm{Ra}$) có phải chất phóng xạ không? Quá trình nhiễm xạ vào cơ thể của hai nguyên tố khác nhau thế nào, có thể tác hại cơ quan nào?','Cả hai đồng vị phóng xạ. Radon là khí, con cháu phân rã có thể hít vào và lắng đường hô hấp, ảnh hưởng phổi; radium có thể vào qua ăn/uống và tích lũy trong xương do tính hóa học gần calcium. Yêu cầu giải thích con đường phơi nhiễm, không suy chẩn đoán cá nhân.','analyze')
# Kết nối tri thức workbook: every numbered position in chapter IV.
B='sbt-kntt'
add(B,'21.1',70,'B21','Đánh dấu (x) vào các cột đúng hoặc sai tương ứng với các nội dung trong bảng dưới đây.','Theo thứ tự các ý: Đúng, Sai, Đúng, Sai, Đúng, Đúng, Đúng, Đúng, Đúng.','understand','true_false',statements=[
(r'Hạt nhân mang điện tích dương, có khối lượng gần bằng khối lượng nguyên tử chứa nó nhưng kích thước nhỏ hơn kích thước nguyên tử cỡ $10^4$ lần.',True),
(r'Hạt nhân mang điện tích dương, có khối lượng nhỏ hơn khối lượng nguyên tử chứa nó rất nhiều và kích thước nhỏ hơn kích thước nguyên tử cỡ $10^4$ lần.',False),
(r'Đơn vị khối lượng nguyên tử kí hiệu là amu; 1 amu bằng $1/12$ khối lượng nguyên tử của đồng vị $^{12}_{6}\mathrm{C}$; $1\ \mathrm{amu}=1{,}66054\times10^{-27}$ kg.',True),
('Hạt nhân nguyên tử được tạo thành bởi các hạt nucleon và electron.',False),('Hạt nhân nguyên tử được tạo thành bởi các hạt nucleon.',True),
('Có hai loại nucleon là proton mang điện tích +1e và neutron trung hòa về điện. Các nucleon có khối lượng xấp xỉ bằng 1 amu.',True),
(r'Kí hiệu hạt nhân $^{A}_{Z}\mathrm{X}$, trong đó X, A, Z lần lượt là kí hiệu hóa học nguyên tố, số khối và số hiệu nguyên tử.',True),
('Các nucleon nằm sát nhau và không chồng lấn vào nhau.',True),
(r'Có thể coi hạt nhân nguyên tử như một quả cầu bán kính R; R phụ thuộc vào tổng số hạt nucleon A theo công thức gần đúng: $R=1{,}2\times10^{-15}A^{1/3}$ (m).',True)])
add(B,'21.2',71,'B21','Hạt nhân nguyên tử gồm','B. Hai loại nucleon là neutron và proton.','remember','choice',['electron và proton.','neutron và proton.','neutron và electron.','electron và pozitron.'],1)
add(B,'21.3',71,'B21','Các nguyên tử là nguyên tử đồng vị khi hạt nhân của chúng có','A. Cùng Z. B và C lặp lại trong bản nguồn, được giữ nguyên.','remember','choice',['cùng số proton.','cùng số neutron.','cùng số neutron.','cùng khối lượng.'],0,status='draft')
add(B,'21.4',71,'B21',r'Hạt nhân $^{31}_{15}\mathrm{P}$ có','C. Z=15, N=31−15=16.','apply','choice',['31 proton và 15 neutron.','16 proton và 15 neutron.','15 proton và 16 neutron.','31 neutron và 15 proton.'],2)
add(B,'21.5',71,'B21',r'Hạt nhân nguyên tử $^{41}_{19}\mathrm{K}$ gồm','B. Z=19, N=41−19=22.','apply','choice',['19 proton và 41 neutron.','19 proton và 22 neutron.','41 proton và 19 neutron.','22 proton và 19 neutron.'],1)
add(B,'21.6',71,'B21',r'Có 22 neutron trong đồng vị $^{42}\mathrm{Ca}$. Số proton trong đồng vị $^{40}\mathrm{Ca}$ là','D. Cùng nguyên tố nên cùng Z=42−22=20.','apply','choice',['28.','26.','24.','20.'],3)
add(B,'21.7',71,'B21',r'Cho số Avogadro $N_A=6{,}02\times10^{23}\ \mathrm{mol}^{-1}$. Số neutron có trong 3,5 g carbon $^{14}_{6}\mathrm{C}$ có giá trị bằng',r'D. $(3{,}5/14)N_A\times8=12{,}04\times10^{23}$.','apply','choice',[r'$3{,}01\times10^{23}$',r'$6{,}02\times10^{23}$',r'$9{,}03\times10^{23}$',r'$12{,}04\times10^{23}$'],3)
add(B,'21.8',71,'B21',r'Cho khối lượng các nguyên tử oxygen và hydrogen lần lượt là 15,999 amu; 1,0078 amu. Số nguyên tử oxygen có trong 5 g nước xấp xỉ bằng',r'A. Mỗi phân tử nước có một O: $N=5N_A/(15{,}999+2\times1{,}0078)\approx1{,}67\times10^{23}$.','apply','choice',[r'$1{,}67\times10^{23}$',r'$1{,}51\times10^{23}$',r'$6{,}02\times10^{23}$',r'$3{,}34\times10^{23}$'],0)
add(B,'21.9',71,'B21',r'Xác định giá trị gần đúng bán kính của hạt nhân $^{238}_{92}\mathrm{U}$. Hạt nhân $^{238}_{92}\mathrm{U}$ có thể tích lớn gấp thể tích của hạt nhân $^{4}_{2}\mathrm{He}$ khoảng mấy lần?',r'$R\approx7{,}44\times10^{-15}$ m; $V_U/V_{He}=238/4=59{,}5$.','apply')
add(B,'21.10',72,'B21',r'Đánh giá kích thước hạt nhân bằng thí nghiệm tưởng tượng sau: cho một quả bóng lăn theo hướng ngẫu nhiên vào dãy quả bóng đường kính a=25 cm gắn chặt cách đều nhau một khoảng b=50 cm (Hình 21.1), xác suất va chạm rồi bật trở lại gần đúng là $P_{bat}=a/b=50\%$, xác suất xuyên qua $P_{xuyen}=1-P_{bat}=50\%$. Nếu a=5 cm thì hai xác suất là 5% và 95%; nếu a=5 mm thì lần lượt 0,5% và 99,5%. Dựa vào sự tương tự với thí nghiệm Rutherford, coi a là kích thước hạt nhân vàng, b là kích thước nguyên tử vàng, tần suất đốm sáng ở vị trí 3 tương ứng bật lại, ở vị trí 1 tương ứng xuyên qua, chứng tỏ kích thước hạt nhân chỉ bằng khoảng $1/10\,000$ kích thước nguyên tử và phù hợp so sánh trong SGK.',r'Nếu b=50 cm và dùng P=a/b thì a=5 cm cho P=10%, a=5 mm cho P=1%, không khớp 5% và 0,5% in trong sách. Không dùng câu làm đề chấm điểm trước khi xác minh hình học và dữ kiện.','analyze',figure=fig(B,'hinh-21-1',72,(.724,.071,.985,.29)),status='draft')
add(B,'21.11',72,'B21',r'Khối lượng nguyên tử của một nguyên tố hóa học là khối lượng trung bình của một nguyên tử chất đó (amu). Trong thiên nhiên có các đồng vị với tỉ lệ xác định, nên khối lượng nguyên tử của một nguyên tố hóa học không bao giờ là số nguyên, trong khi A của một hạt nhân luôn là số nguyên. Neon thiên nhiên gồm $^{20}_{10}\mathrm{Ne}$, $^{21}_{10}\mathrm{Ne}$, $^{22}_{10}\mathrm{Ne}$; Ne-21 chiếm 0,26%, chủ yếu còn lại là hai thành phần kia. Khối lượng nguyên tử neon là 20,179 amu. Tính tỉ lệ phần trăm Ne-20 và Ne-22.',r'Theo gần đúng khối lượng bằng số khối: $20x+21\times0{,}0026+22(0{,}9974-x)=20{,}179$. Ne-20: 90,92%; Ne-22: 8,82%. Mệnh đề “không bao giờ là số nguyên” không đúng tuyệt đối; lời giải chỉ dùng dữ kiện neon.','apply')
add(B,'21.12',72,'B21',r'Khí chlorine là hỗn hợp hai đồng vị bền: $^{35}_{17}\mathrm{Cl}$ có khối lượng nguyên tử 34,969 amu, hàm lượng 75,4%; $^{37}_{17}\mathrm{Cl}$ có khối lượng nguyên tử 36,966 amu, hàm lượng 24,6%. Tính khối lượng nguyên tử của nguyên tố hóa học chlorine.',r'$35{,}460262$ amu.\n$\bar m=34{,}969\times0{,}754+36{,}966\times0{,}246$.','apply','numeric')
add(B,'22.1',73,'B22','Đánh dấu (x) vào các cột đúng hoặc sai tương ứng với các nội dung trong bảng dưới đây.','Theo thứ tự: Đúng, Sai, Đúng, Sai, Đúng, Đúng, Sai, Đúng, Đúng, Đúng, Sai, Đúng, Đúng. Độ bền so sánh theo năng lượng liên kết riêng.','understand','true_false',statements=[
('Phản ứng hạt nhân là quá trình biến đổi từ hạt nhân này thành hạt nhân khác, bao gồm phản ứng hạt nhân kích thích và phản ứng hạt nhân tự phát.',True),
('Trong một phản ứng hạt nhân, luôn cần từ hai hạt tham gia phản ứng trở lên.',False),('Trong phản ứng hạt nhân, số khối và điện tích của hệ được bảo toàn.',True),('Trong phản ứng hạt nhân, số khối, điện tích và khối lượng của hệ được bảo toàn.',False),
('Phản ứng phân hạch là phản ứng hạt nhân trong đó một hạt nhân nặng vỡ thành hai mảnh nhẹ hơn.',True),('Phản ứng tổng hợp hạt nhân là phản ứng trong đó hai hay nhiều hạt nhân nhẹ tổng hợp lại thành một hạt nhân nặng hơn.',True),('Phản ứng tổng hợp hạt nhân là phản ứng trong đó hai hay nhiều hạt nhân trung bình tổng hợp lại thành một hạt nhân nặng.',False),
(r'Độ hụt khối $\Delta m$ là độ chênh lệch tổng khối lượng các nucleon tạo thành hạt nhân và khối lượng hạt nhân: $\Delta m=[Zm_p+(A-Z)m_n]-m_X$.',True),
(r'Năng lượng E và khối lượng m tương ứng của cùng một vật liên hệ theo hệ thức Einstein: $E=mc^2$, c là tốc độ ánh sáng trong chân không.',True),
(r'Năng lượng liên kết riêng của hạt nhân có số khối A bằng $E_{lkr}=E_{lk}/A$, trong đó $E_{lk}$ là năng lượng tối thiểu để tách toàn bộ nucleon ra khỏi hạt nhân, gọi là năng lượng liên kết hạt nhân. Hạt nhân càng bền vững khi $E_{lkr}$ càng lớn.',True),
(r'Hạt nhân càng bền vững khi năng lượng liên kết $E_{lk}$ càng lớn.',False),('Phản ứng hạt nhân kích thích là quá trình các hạt nhân tương tác với các hạt khác (ví dụ hạt nhân, neutron,…) tạo ra các hạt nhân mới. Ví dụ: phân hạch, tổng hợp hạt nhân.',True),('Phản ứng hạt nhân tự phát là quá trình tự phân rã của một hạt nhân không bền vững thành các hạt nhân mới.',True)])
add(B,'22.2',74,'B22','Một hạt nhân có độ hụt khối càng lớn thì hạt nhân đó','A. Năng lượng liên kết tỉ lệ với độ hụt khối.','understand','choice',['có năng lượng liên kết càng lớn.','có năng lượng liên kết không đổi.','có năng lượng liên kết càng nhỏ.','càng bền vững.'],0)
add(B,'22.3',74,'B22','Năng lượng liên kết của hạt nhân bằng','C. Là năng lượng cần tách rời tất cả nucleon.','remember','choice',['năng lượng trung bình liên kết mỗi nucleon trong hạt nhân.','năng lượng cần thiết để tách một nucleon khỏi hạt nhân.','năng lượng cần thiết để tách rời tất cả các nucleon trong hạt nhân.','tích khối lượng hạt nhân với bình phương tốc độ ánh sáng trong chân không.'],2)
add(B,'22.4',74,'B22','Năng lượng liên kết riêng của hạt nhân có giá trị','C. Lớn nhất ở vùng hạt nhân trung bình.','remember','choice',['lớn nhất đối với các hạt nhân nhẹ.','lớn nhất đối với các hạt nhân nặng.','lớn nhất đối với các hạt nhân trung bình.','như nhau với mọi hạt nhân.'],2)
add(B,'22.5',74,'B22',r'Độ hụt khối của hạt nhân $^{A}_{Z}\mathrm{X}$ là',r'A. Tổng khối lượng nucleon tự do trừ khối lượng hạt nhân.','remember','choice',[r'$\Delta m=(Zm_p+Nm_n)-m$',r'$\Delta m=m-Nm_p-Zm_n$',r'$\Delta m=Zm_n-Zm_p$',r'$\Delta m=Zm_n+Nm_p$'],0)
add(B,'22.6',75,'B22','Năng lượng liên kết riêng của hạt nhân','A theo tiêu chí SGK. B cũng có thể đúng với proton đơn lẻ nếu được gọi là hạt nhân đặc biệt; cần xác minh phạm vi trước khi chấm một đáp án.','understand','choice',['càng lớn thì hạt nhân càng bền vững.','có thể bằng 0 đối với các hạt nhân đặc biệt.','càng nhỏ thì hạt nhân càng bền vững.','có thể dương hoặc âm.'],0,status='draft')
add(B,'22.7',75,'B22','Đại lượng nào sau đây đặc trưng cho mức độ bền vững của hạt nhân?','B. Năng lượng liên kết riêng.','remember','choice',['Số neutron.','Năng lượng liên kết riêng.','Số hạt proton.','Năng lượng liên kết.'],1)
add(B,'22.8',75,'B22','Hạt alpha có độ hụt khối 0,0308 amu. Năng lượng liên kết của hạt này bằng',r'D. $E=0{,}0308\times931{,}5\approx28{,}69$ MeV.','apply','choice',['23,52 MeV.','25,72 MeV.','24,72 MeV.','28,70 MeV.'],3)
add(B,'22.9',75,'B22',r'Nếu năng lượng liên kết của hạt nhân helium $^{4}_{2}\mathrm{He}$ là 28,8 MeV thì năng lượng liên kết riêng của nó là','A. 28,8/4=7,20 MeV/nucleon.','apply','choice',['7,20 MeV/nucleon.','14,1 MeV/nucleon.','0,72 MeV/nucleon.','1,4 MeV/nucleon.'],0)
add(B,'22.10',75,'B22','Độ bền vững của hạt nhân càng cao khi','D. So sánh năng lượng liên kết trên mỗi nucleon.','remember','choice',['số nucleon của hạt nhân càng nhỏ.','số nucleon của hạt nhân càng lớn.','năng lượng liên kết của nó càng lớn.','năng lượng liên kết riêng của nó càng lớn.'],3)
add(B,'22.11',75,'B22','Một hạt nhân có 8 proton và 9 neutron. Năng lượng liên kết riêng bằng 7,75 MeV/nucleon. Biết khối lượng proton 1,0073 amu, neutron 1,0087 amu. Khối lượng hạt nhân đó bằng bao nhiêu amu?',r'C. $m=8\times1{,}0073+9\times1{,}0087-17\times7{,}75/931{,}5\approx16{,}995$ amu.','apply','choice',['16,545 amu.','17,138 amu.','16,995 amu.','17,243 amu.'],2)
add(B,'22.12',75,'B22',r'Cho khối lượng nguyên tử helium $m_{He}=4{,}003$ amu; khối lượng electron $m_e=0{,}000549$ amu. Khối lượng hạt alpha là','A. Trừ khối lượng hai electron: 4,003−2×0,000549=4,001902 amu; bỏ qua liên kết electron theo mức chính xác đề.','apply','choice',['4,001902 amu.','4,000921 amu.','4,000975 amu.','4,002654 amu.'],0)
add(B,'22.13',76,'B22',r'Hạt nhân $^{2}_{1}\mathrm{H}$ có khối lượng 2,0136 amu. Năng lượng liên kết của nó bằng',r'D. Lấy $m_p=1{,}00728$, $m_n=1{,}00866$ amu thì $E=(m_p+m_n-2{,}0136)931{,}5\approx2{,}18$ MeV. Dữ kiện in không khớp 2,23 MeV; chưa đưa vào đề chấm điểm.','apply','choice',['1,15 MeV.','4,6 MeV.','3,45 MeV.','2,23 MeV.'],3,status='draft')
add(B,'22.14',76,'B22',r'Cho ba hạt nhân X, Y, Z có số nucleon tương ứng $A_X,A_Y,A_Z$, với $A_X=2A_Y=0{,}5A_Z$. Năng lượng liên kết riêng tương ứng $\Delta E_X,\Delta E_Y,\Delta E_Z$ với $\Delta E_Z<\Delta E_X<\Delta E_Y$. Xếp các hạt nhân theo thứ tự tính bền vững giảm dần:',r'A. Xếp theo năng lượng liên kết riêng: Y, X, Z.','understand','choice',['Y, X, Z.','Y, Z, X.','X, Y, Z.','Z, X, Y.'],0)
add(B,'22.15',76,'B22',r'Cho khối lượng proton, neutron, $^{40}_{18}\mathrm{Ar}$, $^{6}_{3}\mathrm{Li}$ lần lượt 1,0073 amu; 1,0087 amu; 39,9525 amu; 6,0145 amu và $1\ \mathrm{amu}=931{,}5\ \mathrm{MeV}/c^2$. So với năng lượng liên kết riêng Li-6, năng lượng liên kết riêng Ar-40','B. Ar: 8,600375; Li: 5,202875; chênh 3,3975 MeV/nucleon. B=3,42 không khớp dữ kiện đã in ở độ chính xác 0,01; cần xác minh.','apply','choice',['lớn hơn một lượng 5,20 MeV.','lớn hơn một lượng 3,42 MeV.','nhỏ hơn một lượng 3,42 MeV.','nhỏ hơn một lượng 5,20 MeV.'],1,status='draft')
add(B,'22.16',76,'B22','Phần lớn năng lượng giải phóng trong phản ứng phân hạch là','C. Chủ yếu động năng các mảnh phân hạch.','remember','choice',['năng lượng tỏa ra do phóng xạ của các mảnh.','động năng các neutron phát ra.','động năng của các mảnh.','năng lượng các photon của tia gamma.'],2)
add(B,'22.17',76,'B22','Tìm câu sai. Những điều kiện cần phải có để tạo ra phản ứng hạt nhân dây chuyền là','C. Nhiệt độ rất cao là yêu cầu nhiệt hạch, không phải điều kiện bắt buộc của dây chuyền phân hạch.','understand','choice',['sau mỗi lần phân hạch, số neutron giải phóng phải lớn hơn hoặc bằng 1.','lượng nhiên liệu (uranium, plutonium) phải đủ lớn để tạo nên phản ứng dây chuyền.','nhiệt độ phải được đưa lên cao.','phải có nguồn tạo ra neutron.'],2)
add(B,'22.18',76,'B22','Phản ứng nhiệt hạch là','B. Tổng hợp các hạt nhân nhẹ.','remember','choice',['phản ứng hạt nhân tự phát.','phản ứng tổng hợp hạt nhân.','phản ứng phân hạch.','phản ứng tổng hợp hai hạt nhân nặng.'],1)
add(B,'22.19',76,'B22','Nguồn gốc năng lượng của Mặt Trời là do','A. Các phản ứng nhiệt hạch.','remember','choice',['các phản ứng nhiệt hạch xảy ra trong lòng nó.','các phản ứng phân hạch xảy ra trong lòng nó.','các phản ứng hóa học xảy ra trong lòng nó.','các phản ứng hạt nhân tự phát dây chuyền trong lòng nó.'],0)
add(B,'22.20',77,'B22','Phản ứng hạt nhân nào sau đây không phải phản ứng nhiệt hạch?',r'C. Alpha bắn phá nitrogen, tạo oxygen và proton.','understand','choice',[r'$^{2}_{1}\mathrm{H}+{}^{2}_{1}\mathrm{H}\to{}^{4}_{2}\mathrm{He}$',r'$^{2}_{1}\mathrm{H}+{}^{6}_{3}\mathrm{Li}\to2{}^{4}_{2}\mathrm{He}$',r'$^{4}_{2}\mathrm{He}+{}^{14}_{7}\mathrm{N}\to{}^{17}_{8}\mathrm{O}+{}^{1}_{1}\mathrm{H}$',r'$^{1}_{1}\mathrm{H}+{}^{3}_{1}\mathrm{H}\to{}^{4}_{2}\mathrm{He}$'],2)
add(B,'22.21',77,'B22','Tìm phát biểu sai.','A diễn đạt “hai hạt nhân nặng hơn” không đúng định nghĩa tổng hợp; B không chỉ rõ so sánh theo một phản ứng hay theo khối lượng; D phụ thuộc nghĩa kiểm soát và thời điểm. Chưa đủ cơ sở chấm một đáp án.','analyze','choice',['Phản ứng nhiệt hạch là sự tổng hợp hai hạt nhân nhẹ thành hai hạt nhân nặng hơn, còn phân hạch là phá vỡ một hạt nhân nặng thành hai hạt nhân nhẹ hơn.','Năng lượng tỏa ra trong phản ứng nhiệt hạch lớn hơn năng lượng tỏa ra trong phản ứng phân hạch.','Phản ứng phân hạch và phản ứng nhiệt hạch đều là phản ứng hạt nhân tỏa năng lượng.','Hiện nay con người đã kiểm soát được phản ứng phân hạch và phản ứng nhiệt hạch.'],3,status='draft')
add(B,'22.22',77,'B22',r'Quan sát Hình 22.1 cho biết: Các hạt nhân $^{17}_{8}\mathrm{O}$ và $^{1}_{1}\mathrm{H}$ được tạo ra từ các nucleon của hạt nhân nào?',r'Từ He-4 và N-14. Hình nguồn in Ne tại Z=7 (đúng phải là N); giữ nguyên hình và lưu lỗi kí hiệu để rà soát.','understand',figure=fig(B,'hinh-22-1',77,(.144,.452,.95,.645)),status='draft')
add(B,'22.23',77,'B22',r'Biết năng lượng liên kết $^{235}\mathrm{U}$ là 1809,5 MeV, $^{140}\mathrm{Ce}$ là 1180,2 MeV, $^{56}\mathrm{Fe}$ là 494,8 MeV. Hãy so sánh độ bền vững của các hạt nhân này.',r'$E_{lk}/A$: U≈7,700; Ce≈8,430; Fe≈8,836 MeV/nucleon. Độ bền giảm dần: Fe, Ce, U.','apply')
add(B,'22.24',77,'B22',r'Khối lượng hạt nhân alpha $m_{\alpha}=4{,}0015$ amu. Năng lượng liên kết riêng $W_{kr}=7{,}1$ MeV. Tính năng lượng tỏa ra khi 1 mol các hạt alpha được tạo thành từ các hạt nhân proton và neutron.',r'$1{,}71\times10^{25}$ MeV, khoảng $2{,}74\times10^{12}$ J.\nMỗi alpha tỏa $4\times7{,}1=28{,}4$ MeV; nhân $N_A\approx6{,}02\times10^{23}$.','apply','numeric')
add(B,'22.25',77,'B22',r'Biết khối lượng hạt nhân $^{4}_{2}\mathrm{He}$ là $m_{He}=4{,}0015$ amu. Hãy so sánh khối lượng này với tổng khối lượng các nucleon tạo thành nó.',r'$2m_p+2m_n\approx4{,}03188$ amu khi lấy 1,00728 và 1,00866 amu. Lớn hơn khối lượng He; độ hụt khối khoảng 0,03038 amu.','apply')
add(B,'22.26',77,'B22',r'Năng lượng liên kết của hạt nhân nguyên tử $^{14}_{7}\mathrm{N}$ bằng bao nhiêu? Biết hạt nhân nguyên tử này có khối lượng 14,003242 amu.',r'Nếu dùng đúng khối lượng hạt nhân đã cho và $m_p=1{,}00728$, $m_n=1{,}00866$ amu thì $E\approx100{,}920687$ MeV. Dữ kiện gần khối lượng nguyên tử, cần xác minh loại khối lượng.','apply','numeric',status='draft')
add(B,'22.27',78,'B22',r'Trong hai hạt nhân $^{9}_{4}\mathrm{Be}$ và $^{27}_{13}\mathrm{Al}$, hạt nhân nào bền vững hơn? Biết khối lượng hạt nhân Be-9 là 9,00122 amu và khối lượng hạt nhân $^{235}_{92}\mathrm{U}$ là 26,98146 amu.','Dữ kiện U-235=26,98146 amu không phù hợp tên đồng vị; có khả năng là Al-27. Giữ nguyên nguồn, chưa dùng khi chưa xác minh.','apply',status='draft')
add(B,'22.28',78,'B22',r'Phân hạch một hạt nhân $^{235}_{92}\mathrm{U}$ trong lò phản ứng tỏa năng lượng 200 MeV. a) Tính năng lượng tỏa ra khi phân hạch 1 kg U-235. b) Tính lượng than cần đốt để có nhiệt lượng tương đương. Năng suất tỏa nhiệt của than $2{,}93\times10^7$ J/kg.',r'a) $Q=(1000/235)N_A\times200\times1{,}6\times10^{-13}\approx8{,}20\times10^{13}$ J. b) $m_{than}=Q/(2{,}93\times10^7)\approx2{,}80\times10^6$ kg. Dùng $N_A\approx6{,}02\times10^{23}$.','apply')
add(B,'22.29',78,'B22',r'Tổng hợp $^{4}_{2}\mathrm{He}$ từ phản ứng $^{1}_{1}\mathrm{H}+{}^{7}_{3}\mathrm{Li}\to{}^{4}_{2}\mathrm{He}+X$, mỗi phản ứng tỏa 17,3 MeV. Tính năng lượng tỏa ra khi tổng hợp 0,5 mol helium.',r'$2{,}60\times10^{24}$ MeV, khoảng $4{,}17\times10^{11}$ J.\nX là alpha nên mỗi phản ứng tạo 2 He; số phản ứng $0{,}25N_A$, nhân 17,3 MeV.','apply','numeric')
add(B,'22.30',78,'B22',r'Cho phản ứng nhiệt hạch $^{3}_{1}\mathrm{H}+{}^{2}_{1}\mathrm{H}\to{}^{4}_{2}\mathrm{He}+{}^{1}_{0}\mathrm{n}+17{,}5$ MeV. Tính năng lượng tỏa ra khi 1 kg helium được tạo thành. So sánh với năng lượng khi 1 kg $^{235}_{92}\mathrm{U}$ phân hạch.',r'$Q_{He}=(1000/4)N_A\times17{,}5\approx2{,}63\times10^{27}$ MeV. Với 200 MeV/phân hạch U-235, $Q_U\approx5{,}12\times10^{26}$ MeV; tỉ số $Q_{He}/Q_U=5{,}140625$.','apply')
add(B,'23.1',78,'B23','Đánh dấu (x) vào các cột đúng hoặc sai tương ứng với các nội dung trong bảng dưới đây.','Theo thứ tự: Đúng, Sai, Đúng, Sai, Đúng, Sai, Đúng, Đúng, Đúng, Sai.','understand','true_false',statements=[
('Phân rã phóng xạ có tính tự phát và ngẫu nhiên.',True),('Phân rã phóng xạ cần có kích thích để xảy ra.',False),
('Tia phóng xạ là tia không nhìn thấy được, nhưng có các tính chất như ion hóa, gây hiệu ứng quang điện, phát xạ thứ cấp, làm đen kính ảnh, xuyên thấu lớp vật chất mỏng, phá hủy tế bào, kích thích một số phản ứng hóa học,…',True),
('Tia phóng xạ có thể nhìn thấy được và có các tính chất như ion hóa, gây hiệu ứng quang điện, phát xạ thứ cấp, làm đen kính ảnh, xuyên thấu lớp vật chất mỏng, phá hủy tế bào, kích thích một số phản ứng hóa học,…',False),
(r'Các loại tia phóng xạ chính: tia alpha là hạt nhân $^{4}_{2}\mathrm{He}$ phóng ra từ hạt nhân phân rã, tốc độ khoảng $2\times10^7$ m/s; tia beta− (hoặc beta+) là dòng các hạt $^{0}_{-1}\mathrm{e}$ (hoặc $^{0}_{1}\mathrm{e}$), tốc độ xấp xỉ ánh sáng; tia gamma là sóng điện từ có bước sóng rất ngắn, cỡ nhỏ hơn $10^{-11}$ m.',True),
('Tia gamma là chùm hạt mang điện dương và có khả năng đâm xuyên rất lớn.',False),
(r'Số hạt chưa phân rã $N_t$ tại t và số hạt ban đầu $N_0$ liên hệ theo $N_t=N_0 2^{-t/T}=N_0e^{-\lambda t}$; $\lambda=\ln2/T$ là hằng số phóng xạ, T là chu kì bán rã.',True),
(r'Độ phóng xạ H đặc trưng tính phóng xạ mạnh hay yếu của một lượng chất phóng xạ, bằng số hạt nhân phân rã trong một giây; $H_t=\lambda N_t=H_0e^{-\lambda t}$.',True),
('Nguyên tắc an toàn: giữ khoảng cách đủ xa nguồn phóng xạ, dùng tấm chắn đủ tốt và giảm thiểu thời gian phơi nhiễm.',True),('Các nguồn phóng xạ luôn có hại, nên không để chúng xuất hiện.',False)])
add(B,'23.2',79,'B23','Tìm phát biểu sai.','D. Alpha mang điện dương, lệch về bản âm.','understand','choice',['Khi đi qua điện trường giữa hai bản tụ điện, tia alpha bị lệch về phía bản mang điện âm.','Hạt alpha là hạt nhân nguyên tử helium.','Tia alpha làm ion hóa môi trường.','Tia alpha đi qua điện trường giữa hai bản tụ điện sẽ bị lệch về phía bản mang điện dương.'],3)
add(B,'23.3',80,'B23','Tìm phát biểu sai.','D. Trong so sánh SGK, beta có tầm bay lớn hơn alpha.','understand','choice',['Hạt beta− là hạt electron.','Tia beta− có khả năng ion hóa môi trường.','Trong điện trường giữa hai bản tụ điện, tia beta− bị lệch về phía bản mang điện dương.','Tia beta− có tầm bay ngắn hơn tia alpha.'],3)
add(B,'23.4',80,'B23','Tìm phát biểu sai.','D. Positron mang điện dương, lệch về bản âm.','understand','choice',['Tia beta+ có tầm bay xa hơn tia alpha.','Hạt beta+ có cùng khối lượng electron nhưng mang điện tích nguyên tố dương.','Tia beta+ cũng làm ion hóa môi trường nhưng yếu hơn tia alpha.','Tia beta+ bị lệch về phía bản mang điện dương khi đi qua điện trường giữa hai bản tụ điện.'],3)
add(B,'23.5',80,'B23','Công thức nào dưới đây đúng với nội dung định luật phóng xạ?',r'B. $m=m_0e^{-\lambda t}$.','remember','choice',[r'$m=m_0e^{\lambda t}$',r'$m=m_0e^{-\lambda t}$',r'$m=m_0e^{-\lambda/t}$',r'$m=m_0e^{-t/T}$'],1)
add(B,'23.6',80,'B23','Một mẫu phóng xạ có chu kì bán rã 3 ngày. Sau 9 ngày, khối lượng mẫu còn lại 2 kg. Khối lượng ban đầu bao nhiêu?','B. 9 ngày=3T, nên m₀=2×8=16 kg.','apply','choice',['15 kg.','16 kg.','17 kg.','14 kg.'],1)
add(B,'23.7',80,'B23',r'Chu kì bán rã mẫu phóng xạ là 6 giờ. Lúc đầu mẫu có khối lượng $2{,}4\times10^{-2}$ kg. Sau một ngày đêm khối lượng mẫu còn bao nhiêu?',r'B. 24 giờ=4T, $m=m_0/16=1{,}5\times10^{-3}$ kg.','apply','choice',[r'$3\times10^{-3}$ kg.',r'$1{,}5\times10^{-3}$ kg.',r'$2{,}5\times10^{-3}$ kg.',r'$2\times10^{-3}$ kg.'],1)
add(B,'23.8',80,'B23','Sau 3 giờ phóng xạ, số hạt nhân mẫu đồng vị chỉ còn 25% số hạt nhân ban đầu. Chu kì bán rã là','D. 25%=1/4 tương ứng 2T; T=1,5 giờ.','apply','choice',['1 giờ.','2 giờ.','2,5 giờ.','1,5 giờ.'],3)
add(B,'23.9',80,'B23','Một chất phóng xạ lúc đầu có 40 mg, chu kì bán rã 10 giờ. Sau bao lâu khối phóng xạ còn 10 mg?','C. Giảm bốn lần: t=2T=20 giờ.','apply','choice',['10 giờ.','5 giờ.','20 giờ.','40 giờ.'],2)
add(B,'23.10',81,'B23','Dựa vào đồ thị đâm xuyên của tia beta (Hình 23.1), hãy so sánh khả năng đâm xuyên của tia beta trong không khí, cơ thể người, nhôm và chì?','Tại cùng năng lượng, đọc đúng thang riêng của hai trục đứng: tầm bay trong không khí lớn nhất, tiếp đến cơ thể người; nhôm lớn hơn chì. Không so trực tiếp độ cao đường với hai trục có đơn vị thang khác nhau.','analyze',figure=fig(B,'hinh-23-1',81,(.51,.061,.952,.287)))
add(B,'23.11',81,'B23','Hình 23.2 là ảnh chụp hai vết tia alpha xuất phát từ mẫu phóng xạ kích thước rất nhỏ trong buồng sương. Nhận xét đặc điểm hai vết. Buồng sương ở trong từ trường có đường sức vuông góc mặt phẳng ảnh; xác định chiều từ trường.','Hai vết cong cùng phía; bán kính cong thay đổi khi hạt mất động năng. Từ nguồn chung ở phía dưới, alpha đi lên và cong về trái; lực Lorentz với q>0 cho từ trường hướng vào mặt phẳng ảnh.','analyze',figure=fig(B,'hinh-23-2',81,(.648,.339,.845,.537)))
add(B,'23.12',81,'B23',r'Chứng minh rằng sau thời gian $t=xT$, T là chu kì bán rã, số hạt nhân phóng xạ còn lại $N=N_0/2^x$.',r'Thay $t=xT$ vào $N=N_0 2^{-t/T}$: $N=N_0 2^{-x}=N_0/2^x$.','apply')
add(B,'23.13',81,'B23',r'Sau 1 năm, trong 1 miligam $^{144}\mathrm{Ce}$ có $2{,}5\times10^{18}$ hạt bị phân rã. Chu kì bán rã Ce-144 bằng bao nhiêu?',r'$T\approx0{,}762$ năm.\n$N_0=(10^{-3}/144)N_A$; $N=N_0-2{,}5\times10^{18}$; $T=\ln2/\ln(N_0/N)$ năm, dùng $N_A=6{,}02\times10^{23}$.','apply','numeric')
add(B,'23.14',81,'B23',r'Một tượng cổ bằng gỗ có độ phóng xạ H. Mảnh gỗ từ cây vừa chặt có khối lượng tương đương, độ phóng xạ 1,5H. Chu kì bán rã $^{14}\mathrm{C}$ là 5600 năm. Tính tuổi tượng gỗ cổ.',r'$3276$ năm.\n$t=5600\log_2(1{,}5)\approx3275{,}79$ năm, theo T của đề.','apply','numeric')
add(B,'23.15',81,'B23','Để xác định lượng máu trong bệnh nhân, tiêm một lượng nhỏ dung dịch chứa Na-24 (chu kì bán rã 15 giờ), độ phóng xạ 2 µCi. Sau 7,5 giờ lấy 1 cm³ máu, độ phóng xạ 502 phân rã/phút. Tính thể tích máu.',r'$6254$ cm³, khoảng 6,254 L.\nTổng hoạt độ còn $H=2\times10^{-6}\times3{,}7\times10^{10}/\sqrt2$ Bq; hoạt độ mỗi cm³ là 502/60 Bq; V bằng tỉ số. Giả thiết trộn đều, không thải chất đánh dấu.','apply','numeric')
add(B,'24.1',82,'B24','Đánh dấu (x) vào các cột đúng hoặc sai tương ứng với các nội dung trong bảng dưới đây.','Theo ngữ cảnh lò phản ứng phát điện thương mại trong sách: Đúng, Đúng, Sai, Đúng. Ý 2 không dùng làm khẳng định về mọi thiết bị nghiên cứu nhiệt hạch; ý 3 sai vì còn lò nghiên cứu và các chất tải nhiệt khác.','understand','true_false',statements=[
('Công nghệ năng lượng hạt nhân hay năng lượng nguyên tử là loại công nghệ được thiết kế để tách năng lượng hữu ích từ hạt nhân nguyên tử thông qua lò phản ứng hạt nhân có kiểm soát.',True),
('Phương pháp duy nhất được sử dụng trong lò phản ứng hạt nhân hiện nay là phân hạch hạt nhân, mặc dù các phương pháp khác có thể bao gồm tổng hợp hạt nhân và phân rã phóng xạ.',True),
('Tất cả lò phản ứng với nhiều kích thước và mục đích khác nhau đều dùng nước đun nóng tạo hơi nước, rồi chuyển thành cơ năng để phát điện hoặc tạo lực đẩy.',False),
('Sử dụng năng lượng hạt nhân giúp giảm khí thải nhà kính, mang lại nguồn cung điện ổn định, đảm bảo năng lượng bền vững, đem lại lợi ích kinh tế lâu dài.',True)],status='draft')
add(B,'24.2',82,'B24',r'Máy cán vật liệu thành lá có độ dày được điều chỉnh tự động ứng dụng tính đâm xuyên của tia phóng xạ (Hình 24.1). Với nguồn mới, chùm tia giảm độ phóng xạ $n_0=8$ lần khi qua lá thép độ dày $d_0=6$ mm. Nếu cài máy cán lá dày $d_1$, độ phóng xạ giảm $n_1=n_0^{d_1/d_0}$ lần. a) Mô tả nguyên lí hoạt động máy. b) Độ phóng xạ tới đầu thu thay đổi thế nào khi độ dày từ $d_0$ sang $d_1$? c) Thay bằng nguồn đã dùng một chu kì bán rã, giữ thông số cài đặt thì lá có độ dày bao nhiêu? Muốn lá vẫn dày 6 mm cần hiệu chỉnh máy cán tới độ dày nào?',r'a) Đầu thu đo tia truyền qua; bộ điều khiển phản hồi chỉnh con quay. b) $H_1/H_0=8^{1-d_1/6}$. c) Nguồn giảm nửa, để giữ tín hiệu phải có hệ số suy giảm 4: $d=6\log_8 4=4$ mm. Muốn vẫn ra 6 mm với nguồn cũ, chọn tín hiệu bằng nửa ban đầu (tương đương mức cài 8 mm khi quy đổi theo nguồn mới).','analyze',figure=fig(B,'hinh-24-1',82,(.471,.708,1,.974)))
add(B,'24.3',83,'B25',r'Các tính chất phân rã phóng xạ được ứng dụng chế tạo pin nguyên tử có độ tin cậy cao, duy trì dung lượng dài khi dùng nguồn có chu kì bán rã lớn; sử dụng trong thiết bị y tế đặc biệt hoặc du hành vũ trụ dài ngày. Dựa vào thông tin trên Hình 24.2: a) Xác định khối lượng tối thiểu đồng vị cho vào pin, biết $^{238}\mathrm{Pu}$ có T=87,7 năm. b) Suất điện động pin tỉ lệ độ phóng xạ, thay pin khi công suất giảm 50%. Sau bao lâu cần thay pin cho thiết bị điều hòa điện tim?',r'a) Chữ ghi hoạt độ trên ảnh gốc quá mờ để đọc chắc chắn, chưa thể xác định m. b) Nếu tải không đổi và $P\propto U^2\propto H^2$, $P/P_0=1/2$ sau T/2=43,85 năm; nếu giả thiết khác cần nêu rõ. Giữ bản nguồn để rà soát.','analyze',figure=fig(B,'hinh-24-2',83,(.588,.244,.928,.416)),status='draft')
add(B,'24.4',83,'B24','Vì sao các nhà máy điện hạt nhân thường được xây dựng cạnh hồ, sông và bờ biển?','Cần nguồn nước lớn, ổn định cho hệ thống giải nhiệt và bình ngưng; vị trí còn phải đáp ứng an toàn, địa chất và bảo vệ môi trường.','understand')
add(B,'24.5',83,'B24','Liệt kê các nguy cơ ảnh hưởng sức khỏe con người và môi trường nếu xảy ra sự cố tại lò phản ứng hạt nhân.','Phơi nhiễm bức xạ, nhiễm bẩn không khí/nước/đất và chuỗi thực phẩm; ảnh hưởng sức khỏe tùy liều, thời gian, đường tiếp xúc; có thể cần sơ tán, hạn chế sử dụng khu vực và xử lí nhiễm bẩn.','remember')
add(B,'24.6',83,'B24','Nêu vai trò của các nhà máy điện hạt nhân trong đời sống.','Cung cấp điện ổn định, mật độ năng lượng cao, đa dạng nguồn điện và giảm phát thải trong vận hành; cần quản lí an toàn và chất thải.','remember')
add(B,'24.7',83,'B24','Đánh giá các ưu điểm, nhược điểm và cơ hội phát triển của các nhà máy điện hạt nhân.','Đánh giá theo các tiêu chí: cung điện ổn định và phát thải; vốn đầu tư, thời gian xây dựng, chất thải và tháo dỡ; an toàn, nhân lực, hạ tầng và khả năng tài chính. Mỗi nhận định cần nêu lí do; không coi lợi ích là bảo đảm tuyệt đối.','evaluate')
add(B,'24.8',83,'B25','Tại sao sử dụng tia gamma trong chụp ảnh phóng xạ cắt lớp bên trong cơ thể?','Trong SPECT/PET, bức xạ từ chất đánh dấu có thể thoát khỏi cơ thể và được đầu dò ghi nhận để tái tạo ảnh phân bố. Phân biệt với CT dùng tia X; gamma không dùng cho mọi phương pháp cắt lớp.','understand')
add(B,'24.9',83,'B25','Nêu vai trò của y học hạt nhân trong đời sống.','Chất đánh dấu và ghi hình hỗ trợ khảo sát chức năng, chẩn đoán; đồng vị phù hợp dùng điều trị và theo dõi. Luôn gắn mục đích với loại bức xạ và quản lí liều.','remember')
add(B,'24.10',83,'B25','Đánh giá các ưu điểm, nhược điểm và cơ hội phát triển của y học hạt nhân.','Đánh giá khả năng khảo sát chức năng/chẩn đoán và điều trị có mục tiêu; hạn chế gồm phơi nhiễm, chi phí, nguồn đồng vị và yêu cầu nhân lực; cơ hội phụ thuộc hạ tầng, kiểm soát chất lượng, nghiên cứu và tiếp cận của người bệnh.','evaluate')
add(B,'IV.1',84,'B21','Trong hạt nhân','C. Proton và neutron là các nucleon.','remember','choice',['có ba loại hạt là nucleon, proton và neutron.','có ba loại hạt là neutron, proton và electron.','có proton và neutron.','chỉ có neutron.'],2)
add(B,'IV.2',84,'B21','Tìm câu sai. Kí hiệu n là neutron, p là proton. Trong hạt nhân có thể có trường hợp:','C. Neutron tự do không được gọi là hạt nhân nguyên tử với Z=0.','understand','choice',['số n > số p.','số p > số n.','khi số n = 1 thì số p = 0.','khi số p = 1 thì số n = 0.'],2)
add(B,'IV.3',84,'B21',r'Trong hạt nhân $^{14}_{6}\mathrm{C}$ có','B. Z=6, N=14−6=8.','apply','choice',['6 proton và 8 electron.','6 proton và 8 neutron.','6 proton và 14 electron.','6 electron và 8 neutron.'],1)
add(B,'IV.4',84,'B21','Hai hạt nhân có tỉ số số khối là 8 và 27. Tỉ số hai bán kính là:',r'A. $R_1/R_2=(8/27)^{1/3}=2/3$.','apply','choice',[r'$2/3$',r'$8/27$',r'$4/15$',r'$4/9$'],0)
add(B,'IV.5',84,'B21','Thể tích nhỏ nhất có thể có của các hạt nhân là',r'D. Theo mô hình $R=1{,}2A^{1/3}$ fm, lấy A=1: $V=4\pi R^3/3\approx7{,}23\times10^{-45}$ m³.','apply','choice',[r'$1{,}72\times10^{-30}$ m³.',r'$7{,}23\times10^{-15}$ m³.',r'$1{,}23\times10^{-30}$ m³.',r'$7{,}23\times10^{-45}$ m³.'],3)
add(B,'IV.6',84,'B22','Năng lượng liên kết riêng của một hạt nhân là năng lượng liên kết','B. Năng lượng liên kết chia tổng số nucleon.','remember','choice',['tính riêng cho hạt nhân so với hạt nhân khác.','tính cho một nucleon trong hạt nhân.','của hai nucleon khác loại trong hạt nhân.','của hai nucleon cùng loại trong hạt nhân.'],1)
add(B,'IV.7',84,'B23','Phóng xạ là quá trình:','C. Phân rã tự phát làm biến đổi hạt nhân.','remember','choice',['hạt nhân phóng ra các hạt alpha, beta−, beta+ khi bị bắn phá bằng các hạt nhân khác.','hạt nhân tự phát ra các hạt alpha, beta−, beta+ và không biến đổi gì.','hạt nhân tự phát ra các hạt alpha, beta−, beta+ và biến đổi thành một hạt nhân khác.','hạt nhân phát ra các bức xạ điện từ.'],2)
add(B,'IV.8',84,'B23','Trong một phản ứng phóng xạ, khi có tia alpha thì cũng có thể có:','C theo sự phát xạ cùng quá trình: hạt nhân con kích thích có thể phát gamma. Không đồng nhất một lần phân rã với chuỗi nhiều phân rã.','understand','choice',['tia beta−.','tia beta+.','tia gamma.','các tia gamma, beta−, beta+.'],2)
add(B,'IV.9',85,'B23',r'Bình ion hóa gồm bình khí đơn phân tử và hai điện cực kim loại đặt hiệu điện thế 2 kV. Khí bị ion hóa nhờ phóng xạ thì có dòng điện; đo bằng ampe kế rất nhạy (Hình IV.1). a) Vẽ đồ thị độ phóng xạ mẫu $^{220}\mathrm{Rn}$ theo thời gian, ban đầu $H_0$. b) Xác định T của Rn-220. c) Cần tối thiểu 1 mL khí Rn-220 ở điều kiện tiêu chuẩn. Ước tính khối lượng tối thiểu bình từ chất $^{228}\mathrm{Th}$ để duy trì hoạt độ không đổi của Rn-220 trước thí nghiệm. Th-228 phân rã alpha, T=1,9 năm thành Ra-224; Ra-224 phân rã alpha, T=3,6 ngày thành Rn-220.',r'a) $H=H_0 2^{-t/T}$, đồ thị có dạng như dòng điện đo. b) T≈55 s (30→15 pA). c) Giả thiết cân bằng phóng xạ, 365 ngày/năm, thể tích mol 22,4 L/mol: $m_{Th}=228\times(10^{-3}/22{,}4)\times(1{,}9\times365\times86400/55)\approx887$ g. Cần thời gian đạt cân bằng và giữ khí kín.','analyze',figure=fig(B,'hinh-iv-1',85,(.458,.048,.94,.337)))
add(B,'IV.10',85,'B22',r'Hoàn thành các phương trình: a) $^{14}_{7}\mathrm{N}+{}^{4}_{2}\mathrm{He}\to{}^{17}_{8}\mathrm{O}+?$; b) $^{9}_{4}\mathrm{Be}+{}^{4}_{2}\mathrm{He}\to{}^{12}_{6}\mathrm{C}+?$; c) $^{64}_{29}\mathrm{Cu}\to{}^{0}_{1}\mathrm{e}+?$; d) $^{3}_{1}\mathrm{H}\to{}^{3}_{2}\mathrm{H}+?$.','a) proton; b) neutron; c) Ni-64 (kèm neutrino nếu viết đầy đủ). d) Nguồn in H với Z=2, không đúng kí hiệu nguyên tố: phải xác minh, không tự sửa nguồn rồi coi là câu gốc.','apply',status='draft')
add(B,'IV.11',85,'B22',r'Cho $^{27}_{13}\mathrm{Al}$, $^{206}_{82}\mathrm{Pb}$, $m_{Al}=26{,}98153$ amu, $m_{Pb}=205{,}9745$ amu; $m_p=1{,}00728$ amu, $m_n=1{,}00866$ amu, $1\ \mathrm{amu}=931{,}5\ \mathrm{MeV}/c^2$. a) Tính độ hụt khối. b) Tính năng lượng liên kết riêng, cho biết hạt nhân nào bền hơn.',r'a) Al: 0,23435 amu; Pb: 1,69510 amu. b) Al: 8,08508; Pb: 7,66498 MeV/nucleon; Al bền hơn theo tiêu chí bài. Nhãn câu trên nguồn in V.11, nằm trong bài tập cuối chương IV.','apply')
add(B,'IV.12',85,'B23',r'Phòng thí nghiệm mua mẫu phóng xạ nguyên chất có khối lượng $m_0$, T=3465 giây. a) Tính hằng số phóng xạ. b) Sau bao lâu từ lúc mua, 75% chất biến thành chất khác?',r'a) $\lambda=\ln2/3465\approx2{,}0004\times10^{-4}\ \mathrm{s}^{-1}$. b) Còn 25%=1/4 nên t=2T=6930 s.','apply')
add(B,'IV.13',86,'B23',r'Mẫu chất phóng xạ có T=2 ngày, gồm $6{,}4\times10^{11}$ hạt nhân. Mẫu khác có T=3 ngày, gồm $8\times10^{10}$ hạt nhân. Sau bao nhiêu ngày số hạt chưa phóng xạ của hai mẫu bằng nhau?',r'$18$ ngày.\n$8=2^{t(1/2-1/3)}=2^{t/6}$ nên t=18.','apply','numeric')
add(B,'IV.14',86,'B23',r'$^{238}\mathrm{U}$ phân rã thành $^{206}\mathrm{Pb}$, T=$4{,}47\times10^9$ năm. Khối đá chứa 46,97 mg U-238 và 23,15 mg Pb-206. Khi mới hình thành không có chì, tất cả chì hiện có từ U-238 phân rã. Tính tuổi khối đá.',r'$2{,}902\times10^9$ năm.\n$t=T\log_2[1+(23{,}15/206)/(46{,}97/238)]$. Giả thiết hệ kín như đề.','apply','numeric')
add(B,'IV.15',86,'B23',r'Khi cây sống, tỉ lệ $^{12}\mathrm{C}$ và $^{14}\mathrm{C}$ trong cây và khí quyển như nhau. Khi chết C-14 phân rã với T=5730 năm. So sánh phóng xạ beta− của mẫu gỗ cổ và mẫu tương tự còn sống, cả hai cùng chứa một lượng C-14, thấy số hạt C-14 trong mẫu cổ ít hơn 3 lần so với mẫu sống. Xác định tuổi mẫu cổ.',r'Nguồn vừa nói cùng lượng C-14 vừa nói C-14 ít hơn ba lần, mâu thuẫn. Nếu điều kiện là cùng lượng C-12 thì $t=5730\log_2 3\approx9082$ năm; chưa dùng trước khi xác minh điều kiện.','analyze',status='draft')
add(B,'IV.16',86,'B23',r'Tiêm 10 cm³ dung dịch Na-24 nồng độ $10^{-3}$ mol/L vào tĩnh mạch. Sau 6 giờ lấy 10 cm³ máu thấy có $1{,}5\times10^{-8}$ mol Na-24. Tính thể tích máu V, biết T=15 h.',r'$5{,}052$ L.\nSố mol còn $10^{-5}2^{-6/15}$; nồng độ mẫu máu $1{,}5\times10^{-6}$ mol/L; V bằng tỉ số. Giả thiết trộn đều và không đào thải.','apply','numeric')
add(B,'IV.17',86,'B22',r'Giả sử quả bom nguyên tử thả xuống Hiroshima chứa 100 kg quặng uranium, trong đó $^{235}_{92}\mathrm{U}$ chiếm 25%. Mỗi phân hạch U-235 giải phóng trung bình 200 MeV. Năng lượng vụ nổ tương đương bao nhiêu số điện? Khối lượng 1 mol U-235 bằng 235 g.',r'$5{,}70\times10^8$ kWh.\nTheo giả thiết toàn bộ 25 kg U-235 phân hạch: $Q=(25000/235)N_A\times200\times1{,}6\times10^{-13}$ J; chia $3{,}6\times10^6$ J/kWh. Đây là giả thiết bài toán, không phải kiểm chứng dữ kiện lịch sử.','apply','numeric')
add(B,'IV.18',86,'B24',r'Nhà máy điện nguyên tử tiêu thụ trung bình 58,75 g $^{235}_{92}\mathrm{U}$ mỗi ngày, hiệu suất 25%; mỗi phân hạch giải phóng 200 MeV. a) Tính công suất phát điện. b) Mỗi phân hạch giải phóng trung bình 2,5 neutron, sau một ngày số neutron thu được trong lò là bao nhiêu? $N_A=6{,}023\times10^{23}$ hạt/mol; $1\ \mathrm{MeV}=1{,}6\times10^{-13}$ J.',r'a) $P=0{,}25(58{,}75/235)N_A\times200\times1{,}6\times10^{-13}/86400\approx13{,}94$ MW. b) Tổng neutron phát ra $2{,}5(58{,}75/235)N_A=3{,}764375\times10^{23}$. Nếu hỏi neutron tăng ròng, trừ một neutron kích thích mỗi phản ứng: $2{,}258625\times10^{23}$. Phân biệt hai đại lượng khi chấm.','apply')
